"""Authored C1/C2 teaching bridges. No model call and no changes to source lessons."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LESSONS = []

def lesson(id, prerequisites, purpose, blocks, examples, tasks, bridge, sources):
    sections = [dict(title=t, body=b) for t,b in blocks]
    samples = [dict(en=en, ru=ru, why=why) for en,ru,why in examples]
    practice = []
    for i,(prompt,answer,hint,why) in enumerate(tasks):
        model = samples[i]
        practice.append(dict(id=f'prepare-{i+1}', kind='translate' if prompt.startswith('Переведи') else 'write',
            prompt=prompt, context='Учебная мини-ситуация перед основной практикой. '+purpose,
            answers=[answer], hint=hint, explanation=why,
            guidance=dict(title=sections[i]['title'], body=sections[i]['body'], example=model['en'], translation=model['ru']),
            practiceStage='guided'))
    LESSONS.append(dict(lessonId=id, prerequisites=prerequisites.split(), purpose=purpose,
        explanation=sections, examples=samples, practice=practice, beforePractice=bridge, sourceIds=sources.split()))

# Each entry is hand authored. The helper only expands the shared file schema.
lesson('path-inversion','path-polite-questions path-register-b2',
 'Иногда важно выделить ограничение: «Только после проверки», «Ни при каких условиях». Для такого акцента английский меняет порядок слов.',
 [('Сначала обычная фраза','I understood it only later — «Я понял это только позже». Если вынести Only later вперёд, продолжение будет did I understand it. Did показывает прошедшее время, поэтому understand остаётся без окончания. Это утверждение, хотя порядок похож на вопрос.'),
  ('Где переставлять слова','В Only when she called did I understand перестановка происходит в главной части: did I understand. Внутри when she called порядок обычный. Если помощник уже есть, переставляем его: Never have I seen this.'),
  ('Когда это нужно','Инверсия добавляет заметный акцент и часто звучит официальнее. Не превращай каждую фразу в речь со сцены. Другу обычно достаточно I only realized later. Обычные наречия вроде often не требуют такой перестановки.')],
 [('Only later did I understand the problem.','Только позже я понял проблему.','Акцент на том, что раньше понимания не было.'),('Only when she called did I understand.','Только когда она позвонила, я понял.','В when-части не делаем второй вопрос.')],
 [('Переведи с Only later: «Только позже я заметил ошибку». Notice — заметить; the mistake — ошибка.','Only later did I notice the mistake.','После did нужна начальная форма notice.','Прошедшее время уже выражено в did.'),('Начни с Only when: «Только когда он пришёл, мы начали». He arrived; we started.','Only when he arrived did we start.','В when-части оставь he arrived.','Переставляется помощник главной части: did we start.')],
 'В основных заданиях сначала найди границу ограничения, затем собери главную часть. В длинной речи хватит одного-двух осмысленных акцентов.', 'bc-emphasis voa-inversion forum-inversion')

lesson('path-clefts','path-relative-advanced path-register-b2',
 'Собеседник понял событие, но перепутал человека, причину или время. Cleft помогает сказать: «Вот именно эта часть важна».',
 [('Исправляем одну деталь','Maya called — просто сообщение. It was Maya who called — «Позвонила именно Майя». Событие уже обсуждают; мы выделяем исполнителя. После It was ставим ту часть, которую хотим подчеркнуть.'),
  ('Выделяем нужную вещь','What I need is a break означает «Мне нужен именно перерыв». Часть What I need обозначает «то, что мне нужно»; после is называем ответ. Это не вопрос и не попытка сделать фразу сложнее.'),
  ('Сначала реши, что исправляешь','It was yesterday that Maya called исправляет время. It was Maya who called исправляет человека. Не ставь ударную рамку вокруг всей фразы: читателю станет непонятно, с чем ты споришь.')],
 [('It was Maya who sent the email.','Письмо отправила именно Майя.','Исправляем предположение о человеке.'),('What I need is a clear answer.','Мне нужен ясный ответ.','После is — то, чего действительно не хватает.')],
 [('Переведи, выделив человека: «Именно Алекс позвонил».','It was Alex who called.','Начни It was Alex…','Who called остаётся знакомой относительной частью.'),('Переведи с What I need: «Мне нужно время».','What I need is time.','Назови нужную вещь после is.','Рамка выделяет time, а не добавляет новое событие.')],
 'Теперь переходи от одной исправленной детали к ответу на письмо: отдельно назови настоящую проблему и отдельно отвергни чужую догадку.', 'voa-clefts bc-emphasis forum-inversion')

lesson('path-fronting','path-clefts path-participle-clauses',
 'Читателю легче следить за мыслью, если в начале есть знакомая опора, а важное новое сообщение приходит дальше.',
 [('От известного к новому','В разговоре уже обсуждают стоимость. The cost I understand; the delay I do not делает её отправной точкой, а затем противопоставляет задержку. Это заметная перестановка, а не обязательное правило каждого предложения.'),
  ('Длинное объяснение можно отодвинуть','It is hard to explain why the server failed читается легче, чем очень длинная why-часть в начале. It здесь держит место, пока мы не назвали то, что трудно объяснить.'),
  ('Не путай с инверсией','В That part I understand слова I understand идут обычно. Перенос дополнения вперёд сам по себе не требует do I. Проверь также, ясно ли, к чему относятся this, that и it.')],
 [('The price I understand; the delay I do not.','Цену я понимаю; задержку — нет.','Два известных пункта становятся опорами сравнения.'),('It is difficult to explain why the schedule changed.','Трудно объяснить, почему расписание изменилось.','Длинное содержание стоит после короткого начала.')],
 [('Перепиши I understand this part, начиная с This part.','This part I understand.','Не добавляй do перед I.','Переносим только дополнение, не создаём вопрос.'),('Переведи с It is easy: «Легко понять, почему она ушла».','It is easy to understand why she left.','Understand — понять; she left — она ушла.','It позволяет отложить длинную часть why she left.')],
 'В описании процесса проверь каждое начало: есть ли у читателя опора из предыдущей фразы? Не меняй порядок слов ради самого изменения.', 'cam-focus purdue-cohesion')

lesson('path-nominalisation','path-word-formation path-register-b2',
 'Существительное может упаковать действие в одну обсуждаемую вещь: «они отказались» превращается в «их отказ». Но иногда глагол понятнее.',
 [('Действие как тема','The team refused — команда отказалась. The refusal delayed the project — отказ задержал проект. Refusal позволяет сослаться на уже названное действие и обсуждать его последствия.'),
  ('Не прячь действующего человека','We analyzed the results проще, чем An analysis of the results was carried out. Длинная версия не становится точнее только из-за существительных. Если важно, кто решил или ошибся, назови человека или команду.'),
  ('Две полезные проверки','Номинализация — название для превращения действия в существительное. Сначала спроси: это удобная ссылка на уже сказанное? Затем: не потерялось ли кто сделал что? Оставляй существительное ради смысла, а не официального вида.')],
 [('The team refused. The refusal caused a delay.','Команда отказалась. Отказ привёл к задержке.','Вторая фраза подхватывает уже известное действие.'),('We decided to postpone the launch.','Мы решили отложить запуск.','Глагол decide сразу показывает автора решения.')],
 [('Переведи: «Они отказались. Их отказ нас удивил». Refusal — отказ; surprised us — удивил нас.','They refused. Their refusal surprised us.','Во второй фразе используй refusal.','Одно существительное связывает два предложения.'),('Сократи The team made a decision to wait, использовав decided.','The team decided to wait.','Made a decision можно заменить одним глаголом.','Смысл и исполнитель сохранены.')],
 'Перед отчётом потренируй обе стороны: упаковать знакомое действие и распаковать тяжёлую фразу обратно в ясное «кто сделал что».', 'cam-nominalisation purdue-concision')

lesson('path-hedging','path-deduction path-critical-reading',
 'Нужно показать разницу между тем, что мы увидели, и тем, что лишь предполагаем по этим данным.',
 [('Факт и объяснение — разные шаги','18 из 24 участников улучшили результат — наблюдение. Курс вызвал улучшение — уже объяснение причины. Если нет сравнения с другой группой, второе утверждение требует дополнительных оснований.'),
  ('Подбирай силу слова','The results suggest… — результаты указывают на возможный вывод. The results prove… — заявка на гораздо более сильное доказательство. May, appears to, partly помогают назвать конкретную границу, но не нужны все сразу.'),
  ('Не прячь известное за туманом','Число участников можно сообщить прямо. Осторожность нужна там, где начинается догадка. Вместо may possibly perhaps лучше одна ясная оговорка: The sample was small — выборка была маленькой.')],
 [('Scores increased after the course.','Баллы выросли после курса.','Сообщаем последовательность событий.'),('The course may have helped, but there was no comparison group.','Курс, возможно, помог, но группы для сравнения не было.','Возможная причина и ограничение названы отдельно.')],
 [('Сделай вывод осторожнее: The method works for everyone. Используй may и some learners.','The method may work for some learners.','Уменьши и уверенность, и охват.','May — возможный результат; some learners — часть учащихся.'),('Переведи: «Это указывает на улучшение, но выборка мала». Suggests; improvement; the sample.','This suggests improvement, but the sample is small.','Оговорка должна быть конкретной.','Наблюдение не названо окончательным доказательством.')],
 'В аналитической записке сначала перечисли данные, затем вывод, затем то, чего данных пока недостаточно установить.', 'gmu-hedges purdue-synthesis')

lesson('path-reporting-verbs','path-reported-speech path-verb-patterns-advanced',
 'При пересказе важно передать, что человек сделал словами: предложил, признал, пообещал или отрицал. Одного said иногда мало.',
 [('Смысл глагола меняет пересказ','She admitted losing the file означает, что она признала потерю. She denied losing it означает, что она её отрицала. Это не два красивых синонима said: позиции противоположны.'),
  ('У каждого глагола своя рамка','Suggest doing или suggest that we do; advise someone to do; deny doing; promise to do. Учи сочетание целиком. Нельзя переносить рамку advised me to на suggested me to.'),
  ('Не добавляй мотив от себя','Warned — предупредил о риске. Claimed может дистанцировать автора пересказа от утверждения. Если исходная реплика нейтральна, said или reported часто точнее, чем эмоциональный глагол.')],
 [('She suggested waiting until Monday.','Она предложила подождать до понедельника.','Suggest соединяется с -ing без me.'),('He advised me to save a copy.','Он посоветовал мне сохранить копию.','После advise можно назвать человека и to-действие.')],
 [('Переведи: «Она предложила проверить файл». Check the file.','She suggested checking the file.','Suggest + действие на -ing.','Checking называет предложенное действие.'),('Переведи: «Он отрицал, что удалил файл». Deny; delete the file.','He denied deleting the file.','После denied используй deleting.','Это позиция говорящего, а не установленная невиновность.')],
 'В протоколе подпиши владельца каждого утверждения и подбери глагол по исходной реплике, а не ради разнообразия.', 'bc-reporting')

lesson('path-advanced-negation','path-quantifiers-nuance path-critical-reading',
 '«Не все» и «никто» дают разные сведения. Нужно понимать, до какой части сообщения дотягивается not.',
 [('Нарисуй маленькую группу','Из десяти человек ответили семь. Not everyone replied — верно. No one replied — неверно: эта фраза означала бы ноль ответов. Not all само по себе не сообщает точное число.'),
  ('Не обязательно — не то же, что нет','It is not necessarily wrong означает, что ошибочность не следует автоматически. Фраза не обещает, что решение правильное. Это отказ от слишком быстрого вывода.'),
  ('Сделай границу видимой','All students did not pass может быть понято неоднозначно. Для частичного провала напиши Not all students passed; для полного — No students passed. Ясность здесь важнее эффектной конструкции.')],
 [('Not all ten people replied.','Ответили не все десять человек.','По крайней мере один не ответил; сколько ответили, не указано.'),('No one replied.','Никто не ответил.','Количество ответов — ноль.')],
 [('Переведи: «Не все файлы потеряны». All the files; lost.','Not all the files are lost.','Поставь not перед all.','Отрицается потеря всех файлов, а не сохранность каждого.'),('Переведи: «Это не обязательно означает провал». Mean failure.','This does not necessarily mean failure.','Not necessarily — вывод не обязателен.','Фраза не утверждает ни успех, ни провал без данных.')],
 'В публичном уточнении сначала назови исходный смысл без двусмысленности, затем покажи, какое слишком сильное толкование появилось.', 'cam-negation')

lesson('path-ellipsis','path-reported-speech path-verb-patterns-advanced',
 'В разговоре не нужно заново произносить слова, которые собеседник только что услышал. Но оставшаяся часть должна точно указывать на них.',
 [('Оставляем помощника','Maya has finished, but I have not. После have not легко восстановить finished. С прошедшим обычным глаголом остаётся did: She called, but I did not.'),
  ('После to тоже бывает пропуск','I did not want to complain, but I had to. В конце to относится к уже названному complain. Такая короткая форма работает, потому что нужное действие рядом.'),
  ('Проверь, что можно восстановить','I like it, and so does she: does подхватывает like. So is she здесь не подходит. Если перед коротким ответом несколько разных действий, повтори нужный глагол — это избавит от угадывания.')],
 [('She checked it, but I did not.','Она это проверила, а я нет.','Did подхватывает checked.'),('I wanted to leave, but I could not.','Я хотел уйти, но не смог.','После could not понятно пропущенное leave.')],
 [('Сократи I finished, but she did not finish.','I finished, but she did not.','Убери только повтор finish.','Did сохраняет прошедшее время и отрицание.'),('Переведи: «Ему нравится этот план, и мне тоже». Начни He likes this plan.','He likes this plan, and so do I.','С I используй do, а не does или am.','Do заменяет повтор like this plan.')],
 'Прежде чем сокращать диалог, проговори полную версию. После сокращения проверь, что слушатель восстановит именно её.', 'bc-ellipsis cam-substitution')

lesson('path-substitution','path-ellipsis path-countability',
 'One, ones и so позволяют сослаться на уже названный предмет или мысль. Нужно выбрать замену под то, на что она указывает.',
 [('Предмет того же типа','I need a cable. A short one will do — нужен кабель; короткий подойдёт. One заменяет исчисляемый cable. Это может быть другой кабель того же типа, а не тот же самый предмет.'),
  ('Целая мысль','Is the meeting canceled? I think so. So заменяет мысль «встреча отменена». I do not think so отрицает предположение; нельзя понимать so как название самой встречи.'),
  ('Не подставляй one везде','Advice — неисчисляемое. Вместо a good one о совете нужны some useful advice или a useful piece of advice. Проверяй также, ясно ли, какой из нескольких предметов заменён словом one.')],
 [('This cable is broken. I need a new one.','Этот кабель сломан. Мне нужен новый.','One = cable; новый предмет того же типа.'),('Will it work? I hope so.','Это сработает? Надеюсь.','So заменяет it will work.')],
 [('Убери повтор: These chairs are old. We need new chairs.','These chairs are old. We need new ones.','Chairs во множественном числе → ones.','Новые стулья — те же по типу, а не те же физически.'),('Переведи ответ: «Встреча отменена?» — «Я так не думаю».','I do not think so.','So заменяет всю мысль о том, что встреча отменена.','Отрицаем предположение, не называем новый предмет.')],
 'В сравнении методов проверь каждое one, this и it: читатель должен сразу находить заменённое слово или мысль.', 'cam-substitution')

lesson('path-preposition-patterns','path-gerund-infinitive path-collocations-b1',
 'Предлог показывает связь: с кем согласен, на что согласился, за что отвечаешь. Русский предлог не всегда переносится в английский.',
 [('Три разных согласия','Agree with Maya — разделять мнение Майи. Agree on a date — договориться о дате. Agree to a proposal — принять предложение. Выбор зависит от роли следующего слова.'),
  ('Запоминай слово вместе с продолжением','Capable of solving — способный решить; responsible for checking — отвечающий за проверку; insist on checking — настаивать на проверке. После предлога действие обычно оформляется через -ing.'),
  ('Собери личные полезные пары','Не учи список предлогов отдельно. Напиши одну правдивую для себя фразу на сочетание: I rely on my calendar. При повторении меняй только объект, пока сама связь не станет привычной.')],
 [('I agree with you on the goal.','Я согласен с тобой насчёт цели.','With называет человека, on — общий предмет согласия.'),('She insisted on checking the file.','Она настояла на проверке файла.','On входит в рамку insist on; после него checking.')],
 [('Переведи: «Мы договорились о дате». A date.','We agreed on a date.','Речь о совместно выбранном решении: on.','Не путаем это с согласием с человеком.'),('Переведи: «Он способен решить эту проблему». Capable; solve this problem.','He is capable of solving this problem.','Сохрани capable of целиком.','После of ставим solving.')],
 'В письме сначала разложи отношения: кто согласен, с кем, относительно чего и за что отвечает. Затем выбирай связки слов.', 'cam-spoken bc-reporting')

lesson('path-phrasal-nuance','path-everyday-phrasal path-register-b2',
 'Один фразовый глагол может описывать разные события. Учим не перевод двух слов, а маленькую ситуацию и место дополнения.',
 [('Put off: перенести или оттолкнуть','We put off the meeting — перенесли встречу. His tone put me off — его тон отбил желание. Что произошло, видно из участников ситуации: встречу переносят, человека что-то отталкивает.'),
  ('Где стоит it','Bring up the issue и bring the issue up возможны, но с it — bring it up. У короткого местоимения своё место между глаголом и частицей. Не переносим это правило на неразделяемое come across it.'),
  ('Регистр проверяем по выражению','Фразовый глагол не автоматически сленг. Carry out a study уместно в отчёте. Выбирай естественное выражение для ситуации и объясняй смысл нейтральными словами, если читатель может не знать его.')],
 [('We put off the call until Friday.','Мы отложили звонок до пятницы.','Событие переносится на другое время.'),('I will bring it up tomorrow.','Я подниму этот вопрос завтра.','It стоит между bring и up.')],
 [('Переведи: «Мы отложили встречу». Put off; the meeting.','We put off the meeting.','Здесь put off означает postpone.','Meeting — событие, которое перенесли.'),('Замени the issue на it: She brought up the issue.','She brought it up.','Короткое it поставь внутрь сочетания.','Brought up it в этом значении не подходит.')],
 'Перед рассказом выпиши событие для каждого сочетания: перенесли, случайно нашли, подняли вопрос, довели до конца. Так глаголы не станут случайными украшениями.', 'voa-phrasal cam-formal-phrasal')

lesson('path-idioms-context','path-phrasal-nuance path-register-b2',
 'Идиома быстро передаёт знакомую жизненную картину. Без подходящей ситуации образ может быть непонятным или чрезмерным.',
 [('Последняя капля предполагает накопление','The last straw — событие после серии неприятностей, из-за которого терпение закончилось. Один мелкий промах при хороших отношениях ещё не обязательно last straw.'),
  ('Образ привязан к намерению','On the fence — пока не выбрал сторону. A gray area — случай, где правило или граница неясны. Это разные проблемы: собственная нерешительность и неопределённость правила.'),
  ('Всегда умей сказать прямо','В личной истории образ полезен. В официальном сообщении The repeated delays led me to cancel яснее, чем набор идиом. Словарь помогает проверить употребление; буквальный перевод русской идиомы часто создаёт другой образ.')],
 [('Another canceled call was the last straw.','Ещё один отменённый звонок стал последней каплей.','До этого уже были другие неприятности.'),('I am still on the fence about moving.','Я всё ещё не решил, стоит ли переезжать.','Говорящий не выбрал вариант, а не сидит на заборе.')],
 [('Переведи с last straw: «Эта задержка стала последней каплей». The delay.','This delay was the last straw.','Ситуация: задержки повторялись много раз.','Без этой истории выражение звучало бы сильнее, чем основание.'),('Скажи по-английски прямо, без идиомы: I am on the fence about the offer.','I have not decided whether to accept the offer.','Have not decided whether… — ещё не решил, стоит ли…','Прямой пересказ помогает проверить настоящий смысл идиомы.')],
 'Для каждой идиомы сначала придумай причину, по которой она уместна. В рабочей версии передай тот же смысл без образа.', 'cam-last-straw cam-formal-phrasal')

lesson('path-academic-collocations','path-collocations-b1 path-hedging',
 'В научном и рабочем тексте привычные сочетания помогают сразу понять действие: поставить вопрос, провести исследование, подкрепить вывод.',
 [('Учи маленькую связку','Raise a question — поставить вопрос; conduct a study — провести исследование; provide evidence — дать подтверждающие данные. Отдельные переводы raise, conduct, provide здесь менее полезны, чем готовая связь.'),
  ('Evidence не равно окончательное доказательство','Evidence обычно неисчисляемое: some evidence, a piece of evidence. Strong evidence поддерживает вывод, но не автоматически исключает все альтернативы. Research тоже часто неисчисляемое; отдельная работа — a study.'),
  ('Связывай выражение с реальным содержанием','Preliminary findings — предварительные результаты. Напиши, что именно нашли и чего пока не проверили. Академический тон не возникает от длинных слов без данных.')],
 [('The findings raise an important question.','Результаты ставят важный вопрос.','Raise a question — привычное сочетание.'),('We need further evidence to support this explanation.','Нам нужны дополнительные данные в поддержку этого объяснения.','Evidence без неопределённого артикля; сила вывода ограничена.')],
 [('Переведи: «Мы провели исследование». Conduct; a study.','We conducted a study.','Учись вспоминать conduct a study целиком.','A study — одна конкретная работа.'),('Переведи: «Результаты подтверждают это объяснение». The findings; support this explanation.','The findings support this explanation.','Support мягче, чем окончательное prove.','Не объявляем альтернативы исключёнными.')],
 'В аннотации сначала назови вопрос, затем метод, результат и ограничение. Не выдумывай числа или значимость ради убедительного вида.', 'gmu-hedges purdue-synthesis')

lesson('path-lexical-precision','path-word-formation path-collocations-b1',
 'Похожие слова могут оценивать разные стороны одной вещи. Выбор слова должен показывать твою мысль, а не просто звучать умно.',
 [('Результат и затраты — разные вещи','Effective — даёт нужный результат. Efficient — достигает результата с небольшими затратами. Устройство может быстро обрабатывать запросы, но давать неверный ответ: скорость сама по себе не делает его effective.'),
  ('Похожее написание не гарантирует смысл','Economic относится к экономике, economical — экономный в использовании ресурсов. Sensitive — чувствительный, sensible — разумный. Проверяй предложение, а не список переводов.'),
  ('Оценка человека тоже меняется','Confident обычно описывает уверенность; arrogant — высокомерие. Второе слово добавляет неодобрение. Если хочешь сообщить наблюдение без оценки характера, опиши поведение конкретно.')],
 [('The system is fast, but it is not effective.','Система быстрая, но не даёт нужного результата.','Быстрота и результативность разделены.'),('This economical car uses less fuel.','Этот экономичный автомобиль расходует меньше топлива.','Economical описывает затраты, а не экономику страны.')],
 [('Переведи: «Это разумное решение». Sensible; a decision.','This is a sensible decision.','Sensitive означало бы «чувствительный».','Выбрана оценка разумности решения.'),('Скажи двумя короткими фразами: метод экономит время, но не решает проблему. Saves time; solve the problem.','The method saves time, but it does not solve the problem.','Сначала назови выигрыш, затем предел.','Конкретное описание надёжнее расплывчатого good.')],
 'В рекомендации сравнивай по отдельным критериям: результат, время, стоимость, удобство. Под каждое оценочное слово нужна опора.', 'purdue-concision cam-focus')

lesson('path-discourse-markers','path-connectors-basic path-argument-essay',
 'Связка сообщает читателю, как следующая мысль относится к предыдущей: следствие, возражение, уточнение или смена темы.',
 [('Проверь отношение до выбора слова','The test was small. However, the result is useful — польза вопреки ограничению. Therefore означало бы, что польза возникла из-за малого размера. Если логика не совпала, красивое слово не спасёт текст.'),
  ('Разговор и статья звучат по-разному','Well может смягчить начало ответа; anyway возвращает разговор к теме. В записке however и therefore часто яснее. Не заменяй каждое and на moreover ради сложности.'),
  ('Связка не создаёт доказательство','Consequently — «следовательно». Прежде чем писать его, проверь, следует ли второй вывод из первого. Если между мыслями пропущена причина, её нужно объяснить, а не прикрыть переходом.')],
 [('The method is slow. However, it reduces errors.','Метод медленный. Однако он уменьшает число ошибок.','Второй факт перевешивает недостаток, а не вызван им.'),('The file is missing. Therefore, we cannot check it.','Файла нет. Поэтому мы не можем его проверить.','Вторая мысль — следствие первой.')],
 [('Соедини через however: The sample is small. The result is useful.','The sample is small. However, the result is useful.','Польза сохраняется вопреки ограничению.','However указывает на уступку.'),('Переведи: «Данные неполные. Поэтому нам нужна ещё одна проверка». Incomplete; another check.','The data is incomplete. Therefore, we need another check.','Data are incomplete тоже допустимо.','Выбор is или are зависит от принятого стиля; связь остаётся причинной.')],
 'Перед длинным аргументом подпиши на русском связь между соседними тезисами. Затем подбери английские переходы под эту логику.', 'cam-discourse purdue-cohesion')

lesson('path-longform-reading','path-critical-reading path-discourse-markers',
 'В длинном тексте важно не удержать каждое слово, а видеть, кто что утверждает и какую работу выполняет каждый кусок.',
 [('Один абзац — одна работа','Абзац может вводить проблему, приводить пример, возражать или ограничивать вывод. Запиши рядом один короткий глагол: introduces, supports, challenges, limits. Это карта, а не перевод текста.'),
  ('Упомянуть мнение — не значит принять','Critics argue… вводит голос критиков. But the author disagrees показывает ответ автора. Следи за тем, кому принадлежит утверждение, особенно после цитаты.'),
  ('Отделяй пример от основания','Один случай показывает, что нечто возможно. Он не устанавливает, как часто это происходит. Для вывода о большинстве нужны другие данные. В ответе называй конкретную границу, а не просто «текст слабый».')],
 [('The author mentions the objection but does not accept it.','Автор упоминает возражение, но не принимает его.','Разделены чужой голос и позиция автора.'),('This example shows a possibility, not its frequency.','Этот пример показывает возможность, а не её частоту.','Указано, чего именно пример не доказывает.')],
 [('Прочитай: Some critics call the plan unfair. I disagree. Напиши, принимает ли автор мнение критиков. Ответ на английском одним предложением.','The author does not agree that the plan is unfair.','I disagree относится к мнению из предыдущей фразы.','Не приписываем процитированное мнение автору.'),('Переведи: «Пример иллюстрирует мысль, но не доказывает её». Illustrates the point; prove it.','The example illustrates the point, but it does not prove it.','Illustrate — показать на примере.','Сохраняем разницу между иллюстрацией и доказательством.')],
 'Сначала разбери короткий исходный фрагмент. Добавляя собственные идеи в обзор, явно отделяй их от того, что было в тексте.', 'purdue-synthesis uvu-rhetoric')

lesson('path-lecture-listening','path-connected-speech path-hedging',
 'На лекции важная оговорка может прозвучать тише и короче главного тезиса. Нужно услышать не только тему, но и границы вывода.',
 [('Лови поворот мысли','However, in some cases, more precisely сообщают, что мысль уточняют. Не записывай только существительные: рядом с тезисом оставь ограничение. «Помогает — но не всем» точнее списка слов «метод, люди, результат».'),
  ('Два прослушивания — две задачи','Сначала поймай главный вопрос и ответ. Затем переслушай числа, отрицания и условия. Текст открывай после своей попытки: иначе не поймёшь, что услышал сам, а что прочитал.'),
  ('Честно назови вид практики','Синтетическая озвучка полезна для тренировки фраз, но не воспроизводит все перебивания и акценты живой лекции. Если работаешь только с текстом, это конспектирование прочитанного, а не проверка слуха.')],
 [('The method helps, but not in every case.','Метод помогает, но не во всех случаях.','Оговорка ограничивает главный тезис.'),('If I understood correctly, this is a preliminary result.','Если я правильно понял, это предварительный результат.','Мы проверяем понимание и сохраняем статус результата.')],
 [('Прочитай учебную реплику: The plan is useful, but only for small groups. Передай одним предложением главный предел.','The plan is useful only for small groups.','Only — важная часть, её нельзя выкинуть.','Это подготовка к слушанию, сейчас исходник дан письменно.'),('Переведи: «Если я правильно понял, решение пока не окончательное». The decision; final yet.','If I understood correctly, the decision is not final yet.','Уточняй понимание без превращения догадки в факт.','Not final yet сохраняет временный статус.')],
 'Включи озвучку, скрой текст и выпиши тезис с ограничением. Если звук недоступен, выполни текстовый вариант и не считай его аудированием.', 'rachel-stress cam-discourse')

lesson('path-prosody','path-connected-speech path-clefts',
 'Одни и те же слова отвечают на разные скрытые вопросы, если выделить голосом другое слово.',
 [('Кого исправляешь','I sent the file: ударное I может означать «именно я, не Алекс». Ударное FILE может исправлять «ты отправил ссылку?». Слова те же; контраст выбирает выделение.'),
  ('Ударение — не просто громкость','Важное слово часто становится длиннее и меняет высоту тона; соседние слова сокращаются. Не нужно выкрикивать каждое значимое существительное. Сначала выбери одну мысль, которую слушатель мог понять неправильно.'),
  ('Контекст надёжнее угадывания','Одна интонация не гарантирует единственного намерения. Добавь ясное продолжение: I sent the file, not the link. TTS может не передать нужный контраст; для проверки слушай собственную запись и человеческий образец.')],
 [('I sent the file, not Alex.','Файл отправил я, а не Алекс.','Контраст относится к исполнителю.'),('I sent the file, not the link.','Я отправил файл, а не ссылку.','Контраст относится к предмету.')],
 [('Тебя спросили, отправил ли файл Алекс. Напиши короткое исправление, начав с I.','I sent the file, not Alex.','Меняется исполнитель, событие остаётся.','При произнесении выдели I.'),('Тебе сказали: You sent the link. Исправь: ты отправил файл.','I sent the file, not the link.','Сохрани человека и действие, исправь предмет.','При произнесении выдели file; явный контраст поддерживает смысл.')],
 'Сначала напиши, какое недопонимание исправляешь. Потом запиши голосом две версии и сравни с этим намерением. Автоозвучка не является оценкой твоей интонации.', 'rachel-stress bc-emphasis')

lesson('path-synthesis','path-longform-reading path-reporting-verbs',
 'Два пересказа рядом ещё не дают общего ответа. Синтез связывает источники вокруг вопроса: в чём они совпали, разошлись и что из этого следует.',
 [('Сначала один общий вопрос','Один автор пишет о доступе к занятиям, другой о результатах экзамена. Это не обязательно спор: они могут измерять разные вещи. Назови общий вопрос и проверь, сопоставимы ли ответы.'),
  ('Пиши по теме, а не по очереди источников','Вместо «сначала весь A, потом весь B» собери абзац о доступе, затем о качестве. В каждом подпиши, кто что сообщает. Собственная связка должна отличаться от утверждений авторов.'),
  ('Не выжимай согласие','Если источник молчит о стоимости, это не значит, что он считает её низкой. Отметь пробел. Общий вывод может быть условным: полезно при одном условии, недостаточно данных по другому.')],
 [('Both sources discuss access, but only B reports costs.','Оба источника обсуждают доступ, но только B сообщает расходы.','Сходство темы не означает одинакового содержания.'),('Taken together, the sources support a limited trial.','Вместе источники дают основания для ограниченной пробы.','Это собственный соразмерный вывод из сопоставления.')],
 [('Дано: A сообщает о росте посещаемости. B сообщает о высоких расходах. Соедини два факта одним английским предложением.','A reports higher attendance, while B reports high costs.','While здесь сопоставляет два аспекта.','Не выдумываем, что B отрицает рост посещаемости.'),('Переведи: «Оба автора поддерживают пробный запуск, но расходятся в оценке затрат». Support a trial; disagree about costs.','Both authors support a trial, but they disagree about costs.','Сначала общее, затем конкретная разница.','Указан предмет согласия и предмет спора.')],
 'Перед обзором сделай таблицу «вопрос — A — B — неизвестно». Каждый общий вывод проверь по заполненным ячейкам.', 'purdue-synthesis')

lesson('path-proposal','path-synthesis path-argument-essay',
 'Хорошее предложение помогает принять решение: что сделать, почему именно это, сколько потребуется и когда пересмотреть выбор.',
 [('Рекомендация видна сразу','I propose a two-week trial — понятное действие. Улучшить всё сразу — не план. Назови небольшой проверяемый шаг, ответственного и срок, если они известны.'),
  ('Сравни варианты по одному критерию','Если цель — доступность, объясни, как каждый вариант помогает участникам. Если ограничение — бюджет, покажи затраты. Нельзя один вариант хвалить за скорость, а другой отвергать за цвет, не объяснив связь с целью.'),
  ('Риск и правило остановки','A trial is useful if… называет условие. We will review it after… задаёт проверку. Уверенный тон не требует обещать успех: сильнее объяснить, как заметим проблему и изменим решение.')],
 [('I propose a two-week trial before a full launch.','Я предлагаю двухнедельную пробу перед полным запуском.','Рекомендация ограничена и выполнима.'),('We will review costs and attendance after two weeks.','Через две недели мы проверим расходы и посещаемость.','Названы срок и критерии проверки.')],
 [('Переведи: «Я предлагаю небольшой пробный запуск». A small trial.','I propose a small trial.','Propose + существительное или -ing.','Читатель сразу видит конкретное действие.'),('Добавь условие к We can extend the trial: расходы останутся в пределах бюджета. Costs stay within the budget.','We can extend the trial if costs stay within the budget.','If ограничивает разрешение расширять пробу.','Обещание не становится безусловным.')],
 'Собери документ из решения, двух оснований, сильного возражения и проверки результата. Длинные исходные задания теперь используют уже разобранные части.', 'purdue-synthesis gmu-hedges')

lesson('path-scope-ambiguity','path-advanced-negation path-clefts',
 'Иногда предложение грамматически верно, но допускает два смысла. Наша задача — заметить развилку и написать именно тот смысл, который нужен.',
 [('Что ограничивает only','Only Maya emailed Dan: письмо отправила только Майя. Maya emailed only Dan: получатель только Дэн. Слова почти те же, но ограничение относится к разным участникам.'),
  ('Общее дело или отдельное для каждого','Every reviewer read a report может означать один общий отчёт или по отчёту на человека. Если различие важно, добавь the same report либо a different report. Не заставляй читателя додумывать распределение.'),
  ('Редактура начинается с вопроса','Неясность не всегда ошибка: контекст может всё прояснять. В инструкции или договорённости лучше убрать её заранее. Спроси себя: какой второй смысл мог бы честно увидеть человек без моей предыстории?')],
 [('Only Maya checked the report.','Отчёт проверила только Майя.','Ограничение относится к проверяющему.'),('Maya checked only the report.','Майя проверила только отчёт.','Ограничение относится к проверенному предмету.')],
 [('Переведи: «Только Алекс видел ошибку». Alex; saw the error.','Only Alex saw the error.','Only должно ограничивать человека.','Не утверждаем, что Алекс видел только ошибку.'),('Уточни Every reviewer read a report: все читали один и тот же отчёт.','Every reviewer read the same report.','The same — один и тот же.','Убираем возможность понимать это как разные отчёты.')],
 'В длинных ответах ищи only, all, each и местоимения. Для каждой спорной фразы запиши два возможных смысла и выбери нужный.', 'cam-negation cam-focus')

lesson('path-counterfactual-inversion','path-third-conditional path-inversion',
 'Можно выразить знакомое условие без if. Смысл условия сохраняется, но фраза часто звучит более формально.',
 [('Другое прошлое','If I had known → Had I known. Убираем if и ставим had перед человеком. Продолжение остаётся знакомым: I would have called. Не добавляем did: нужный помощник had уже есть.'),
  ('Возможная будущая ситуация','Should you need help, call me — «Если вам понадобится помощь, позвоните». Это формальная рамка возможного случая, а не совет, что помощь должна понадобиться. Обычное If you need help тоже правильно.'),
  ('Не инвертируй любое условие','Этот приём связан с had, should и were. Нельзя просто превратить If he calls в Calls he. Сначала восстанови вариант с if и проверь время и реальность ситуации.')],
 [('Had I known, I would have waited.','Если бы я знал, я бы подождал.','Воображаемое другое прошлое, не вопрос.'),('Should you need a copy, email me.','Если вам понадобится копия, напишите мне.','Формальная условная инструкция.')],
 [('Перепиши без if: If we had checked, we would have noticed it.','Had we checked, we would have noticed it.','Переставь только had и we.','Вторая часть сохраняет would have noticed.'),('Переведи с Should: «Если вам понадобится помощь, позвоните мне».','Should you need help, call me.','После should — начальная форма need.','Это условие, а не обязанность нуждаться в помощи.')],
 'В официальном тексте используй такую форму там, где она естественна. Умение объяснить ту же мысль с if важнее количества инверсий.', 'bc-conditionals')

lesson('path-aspect-viewpoint','path-past-perfect-continuous path-verb-patterns-advanced',
 'Форма глагола выбирает ракурс: событие целиком, процесс в определённый момент или временное поведение. Ракурс влияет на то, что услышит собеседник.',
 [('Целиком или изнутри','I read the report yesterday обычно представляет прочтение как законченное событие. I was reading it at six помещает нас внутрь процесса и не сообщает, дочитал ли я. Время и завершённость — не одно и то же.'),
  ('Свойство и поведение','He is rude описывает человека или его манеру в целом. He is being rude выделяет нынешнее поведение. Being не просто делает фразу «сейчас»: оно позволяет представить проявление качества как временное действие.'),
  ('Значение самого глагола тоже важно','I think it is useful — мнение. I am thinking about it — обдумываю. Не все глаголы одинаково охотно принимают continuous: сначала проверь, какое значение используешь.')],
 [('I was reading the report when she called.','Я читал отчёт, когда она позвонила.','Звонок попадает внутрь процесса; завершение не указано.'),('He is being unusually quiet today.','Сегодня он ведёт себя необычно тихо.','Описывается сегодняшнее поведение, а не постоянный характер.')],
 [('Переведи: «В шесть я писал ответ». At six; write a reply.','At six, I was writing a reply.','Нужен взгляд внутрь процесса.','Не утверждаем, что ответ уже был готов к шести.'),('Передай временное поведение: «Ты сейчас ведёшь себя несправедливо». Unfair.','You are being unfair.','Используй are being, если речь о поведении в этой ситуации.','Фраза критикует проявление, а не обязательно весь характер человека.')],
 'Выбирая форму в рассказе, объясни, что хочешь показать: начало, процесс, завершение или временное проявление. Не заменяй формы механически.', 'cam-aspect')

lesson('path-modal-remoteness','path-second-conditional path-polite-questions',
 'Прошедшая форма не всегда про прошлое. Иногда она отодвигает просьбу или предположение, чтобы звучать менее категорично.',
 [('Время узнаём по ситуации','Could you send it now? — просьба сейчас. Could не переносит отправку во вчера. Сравни I could swim at six: здесь контекст действительно задаёт прошлое.'),
  ('Вежливое отступление','I was wondering if you could help — осторожный вход в просьбу. Мы не обязаны понимать was wondering как давно законченное размышление. Форма оставляет собеседнику больше пространства ответить.'),
  ('Осторожность не должна скрывать задачу','В длинной цепочке might perhaps possibly читатель может не увидеть просьбу. Назови действие и нужный срок. Важное требование безопасности не стоит превращать в необязательную догадку.')],
 [('Could you check this today?','Не могли бы вы проверить это сегодня?','Today показывает настоящее/ближайшее действие.'),('I was wondering if we could move the call.','Я хотел спросить, можно ли перенести звонок.','Прошедшая форма смягчает вход в просьбу.')],
 [('Переведи вежливую просьбу на сегодня: «Не могли бы вы прислать файл сегодня?»','Could you send the file today?','Could здесь не про вчера.','Речь о просьбе, а не о способности в прошлом.'),('Смягчи Can we change the date?, начав с I was wondering.','I was wondering if we could change the date.','Внутри if-части прямой порядок we could.','Форма меняет подачу просьбы, а не нужное действие.')],
 'В основных заданиях отдельно определи время действия и отношение говорящего. Тогда прошедшая форма не будет автоматически превращаться в прошлое событие.', 'cam-politeness')

lesson('path-determiner-nuance','path-articles-advanced path-quantifiers-nuance',
 'Артикли и слова вроде any, some, few не просто стоят перед существительным. Они показывают, как говорящий представляет предмет и количество.',
 [('Один экземпляр или узнаваемый предмет','A director called — позвонил какой-то директор. The director called — адресат должен понять, какой именно. The не обязательно означает единственный во вселенной: достаточно общей ситуации.'),
  ('Количество плюс оценка','A few questions remain — вопросы ещё есть, какое-то количество. Few questions remain обычно подчёркивает, что их мало. Само число может совпадать, но оценка говорящего меняется.'),
  ('Any зависит от рамки','Choose any file разрешает выбрать любой. I do not have any files сообщает отсутствие файлов. Не присваивай any один русский перевод вне предложения.')],
 [('A few people stayed to help.','Несколько человек остались помочь.','В центре внимания наличие помощников.'),('Few people stayed to help.','Мало кто остался помочь.','В центре внимания недостаточное или небольшое число.')],
 [('Переведи с положительным акцентом на наличие: «У нас есть немного времени».','We have a little time.','Time неисчисляемое; a little подчёркивает, что запас есть.','Little time без a чаще подчёркивает нехватку.'),('Переведи разрешение: «Выбери любой файл».','Choose any file.','Any здесь расширяет выбор.','Это не отрицательная конструкция с отсутствием файлов.')],
 'Перед объяснением выбора спроси: предмет уже узнаваем? количество подаётся как запас или нехватка? выбор свободный или ограниченный?', 'cam-determiners')

lesson('path-information-density','path-nominalisation path-fronting',
 'Короткий текст может быть трудным, если в каждом существительном спрятана цепочка действий. Учимся упаковывать и распаковывать сведения без потери смысла.',
 [('Найди главное существительное','A revised staff training schedule — основа schedule, то есть расписание. Остальные слова уточняют, какое. В английской группе главное существительное часто стоит в конце, но читать смысл удобнее от него.'),
  ('Верни скрытые действия','The rejection of the proposal delayed work можно распаковать: The board rejected the proposal, so work was delayed — если board известен из контекста. Нельзя выдумывать исполнителя только ради активного залога.'),
  ('Плотность выбирают под задачу','Специалист узнает короткий термин сразу; новичку потребуется пояснение. Разбить длинную фразу на две иногда точнее, чем заменить понятное описание одним редким словом.')],
 [('We revised the schedule for staff training.','Мы изменили расписание обучения сотрудников.','Скрытое изменение стало явным действием.'),('The proposal was rejected. This delayed the work.','Предложение отклонили. Это задержало работу.','Две короткие фразы сохраняют связь без выдуманного исполнителя.')],
 [('Распакуй the evaluation of the new system в предложение «Мы оценили новую систему». Evaluate.','We evaluated the new system.','Существительное evaluation превращается в evaluated.','В учебной ситуации исполнитель задан: we.'),('Переведи двумя короткими предложениями: «Решение отложили. Это задержало запуск». Postpone; delay the launch.','The decision was postponed. This delayed the launch.','Исполнитель неизвестен — не придумывай его.','Распаковка сохраняет причинную связь и границу известного.')],
 'Сначала подчеркни факты, которые нельзя потерять. Сокращай только после того, как понятны участники, действия и связи.', 'purdue-concision purdue-cohesion')

lesson('path-emphasis-restraint','path-clefts path-hedging',
 'Сильная мысль не требует always, obviously и absolutely в каждой строке. Точный акцент делает важное заметным, не раздувая утверждение.',
 [('Выбери один центр','The main issue is access сразу называет главное. Три усилителя перед issue не объяснят, почему доступ важен. После акцента добавь конкретную опору.'),
  ('Сильнее звучит проверяемое','Everyone hated the plan — широкое заявление. Seven of ten participants rejected it — точное, если такие данные действительно есть. Числа нельзя изобретать ради убедительности.'),
  ('Уточнение не равно слабость','It is a serious risk, not a certainty позволяет держать две мысли: риск важен и исход не предрешён. Убирая преувеличение, не стирай саму проблему.')],
 [('The main problem is the missing safety check.','Главная проблема — отсутствующая проверка безопасности.','Важность связана с конкретным пропуском.'),('This is a real risk, but not a guaranteed outcome.','Это реальный риск, но не гарантированный исход.','Сила оценки и степень уверенности разделены.')],
 [('Замени расплывчатое This is absolutely, completely terrible на конкретное: не указан срок. Deadline.','The main problem is the missing deadline.','Назови проверяемую проблему.','Читатель понимает, что именно исправлять.'),('Переведи: «Риск серьёзный, но провал не неизбежен». Serious; failure; inevitable.','The risk is serious, but failure is not inevitable.','Не превращай осторожность в отрицание риска.','Сохраняем и серьёзность, и неопределённость исхода.')],
 'В публичном тексте проверь каждый усилитель: добавляет ли он нужную границу или лишь эмоцию? Под важной оценкой оставь конкретный факт.', 'gmu-hedges uvu-rhetoric')

lesson('path-semantic-prosody','path-lexical-precision path-phrasal-nuance',
 'У слова бывает привычное окружение, которое приносит оценку даже без явно положительного или отрицательного прилагательного.',
 [('Соседи влияют на впечатление','Cause часто встречается с problem, damage, delay. Bring about может нейтрально называть изменение. Это склонности употребления, а не запрет сочетать cause с положительным результатом.'),
  ('Проверь несколько контекстов','Одно предложение из словаря показывает возможность, но не частоту и не весь тон. Посмотри несколько примеров, обрати внимание на соседние слова и жанр. Не объявляй слово «всегда негативным» по одному случаю.'),
  ('Выбор должен совпасть с намерением','Если описываешь полезное изменение, проверь, не звучит ли выбранное выражение как обвинение или насмешка. При сомнении используй нейтральное led to и конкретно назови результат.')],
 [('The change caused several delays.','Изменение вызвало несколько задержек.','Обычное окружение cause связано с нежелательным последствием.'),('The change led to better access.','Изменение улучшило доступ.','Нейтральная связь причины и результата без скрытой жалобы.')],
 [('Переведи нейтрально: «Изменение привело к новым возможностям». Led to; new opportunities.','The change led to new opportunities.','Не добавляй осуждающую оценку.','Led to оставляет оценку самим названным последствиям.'),('Сделай вывод осторожнее: Cause is always negative.','Cause often occurs with negative outcomes, but not always.','Often, а не always; outcome — результат.','Сочетаемость — тенденция, не абсолютное грамматическое правило.')],
 'Собирая свои примеры, записывай не только перевод, но и жанр, соседние слова и отношение говорящего. Для утверждения о частоте нужен корпус, а не догадка.', 'oup-prosody')

lesson('path-metaphor','path-idioms-context path-lexical-precision',
 'Метафора предлагает увидеть одну ситуацию через другую: спор как бой, план как путь, проблему как узкое место. От образа зависит, какие действия кажутся естественными.',
 [('Назови картину за словами','We need to defend our position рисует спор как противостояние. We need to find common ground предлагает общую площадку. Оба выражения могут обсуждать тот же разговор, но направляют внимание по-разному.'),
  ('Сначала буквальное сообщение','The project hit a wall означает, что продвижение остановилось из-за препятствия. Чтобы понять, какое решение нужно, назови препятствие прямо: денег нет, разрешение задержано, данные отсутствуют.'),
  ('Образ не доказывает вывод','Назвать реформу лекарством ещё не значит показать, что она поможет. Проверь, что образ подчёркивает и что скрывает. Не смешивай несколько картин так, чтобы читатель потерял сцену.')],
 [('We need to find common ground.','Нам нужно найти точки согласия.','Пространственный образ направляет к сотрудничеству.'),('The project hit a wall because funding stopped.','Проект зашёл в тупик, потому что финансирование прекратилось.','После образа названа конкретная причина.')],
 [('Скажи без метафоры: The project hit a wall.','The project could not move forward.','Передай остановку продвижения, не придумывая причину.','Буквальный пересказ проверяет смысл образа.'),('Переведи: «Нам нужны точки согласия, а не победитель». Common ground; a winner.','We need common ground, not a winner.','Две рамки: совместное решение и соревнование.','Выбор образа соответствует цели разговора.')],
 'При разборе текста сначала переведи образ в обычное утверждение, затем объясни, как образ влияет на читателя. Это не поиск скрытого смысла любой ценой.', 'uvu-rhetoric')

lesson('path-irony','path-reading-inference path-prosody',
 'Человек может произнести похвалу, чтобы выразить досаду. Но без контекста те же слова могут быть искренними.',
 [('Слова и ситуация расходятся','Wonderful timing после сорванного из-за опоздания звонка может быть иронией. При удачном совпадении это обычная похвала. Значение возникает из ситуации, отношений и голоса вместе.'),
  ('Не выдавай догадку за доказательство','Сухая манера или короткое сообщение сами по себе не доказывают сарказм. В переписке лучше уточнить: Do you mean that literally? Ирония может быть добродушной, а может задевать.'),
  ('Умей снять второй слой','Если адресат понял слова буквально, скажи прямо: I was frustrated about the delay. Разъяснение полезнее, чем обвинять его в отсутствии чувства юмора. В важных инструкциях избегай двусмысленного юмора.')],
 [('Great, another canceled meeting.','Ну прекрасно, ещё одна отменённая встреча.','В контексте повторной досады great вероятно иронично.'),('Great, the meeting is confirmed.','Отлично, встреча подтверждена.','При желаемом результате похвала может быть буквальной.')],
 [('Опоздание сорвало планы. Объясни по-английски возможный смысл Wonderful timing, используя may.','The speaker may be expressing frustration about the delay.','Не объявляй чтение единственно возможным.','May сохраняет статус интерпретации контекста.'),('Переведи нейтральное уточнение: «Ты говоришь это буквально?»','Do you mean that literally?','Literally — в прямом смысле.','Проверяем намерение вместо угадывания сарказма.')],
 'В основных заданиях назови слова, контекст и альтернативное буквальное чтение. Затем реши, какая интерпретация лучше подкреплена.', 'cam-spoken uvu-rhetoric')

lesson('path-implicature','path-reading-inference path-modal-remoteness',
 'Собеседник иногда сообщает больше, чем произносит прямо. Нужно понимать намёк и одновременно помнить, что это вывод, который можно уточнить.',
 [('Ответ может обходить прямое да или нет','На Shall we go out? человек отвечает I have an early meeting. Возможно, он отказывается из-за раннего утра. Буквально сообщён только факт о встрече; отказ — вывод из ситуации.'),
  ('У вывода есть запасной вариант','Тот же ответ может означать «пойдём, но ненадолго». Проверь: Do you mean you would rather stay in? Не превращай предположение в цитату «он точно сказал нет».'),
  ('Предполагаемое заранее тоже проверяем','Have you stopped working nights? подаёт прежнюю ночную работу как уже известную. Если это неверно, можно ответить I never worked nights. Не обязан принимать скрытую предпосылку вопроса.')],
 [('I have an early meeting tomorrow.','Завтра у меня ранняя встреча.','В ответ на приглашение может намекать на ограничение, но не является прямым отказом.'),('Do you mean you would rather stay home?','Ты имеешь в виду, что предпочёл бы остаться дома?','Догадка превращена в проверяемое уточнение.')],
 [('На приглашение человек сказал I have to finish this tonight. Напиши осторожный вывод с may.','They may be saying that they cannot come.','May оставляет возможность другого намерения.','Пересказ не выдаёт намёк за точную цитату отказа.'),('Переведи: «Я этого не утверждал; я лишь предположил». State that; suggest it.','I did not state that; I only suggested it.','Отдели явное утверждение от предложения мысли.','Это помогает исправить слишком сильный пересказ.')],
 'В разборе помечай отдельно: произнесено, принято за известное, выведено из контекста. Последнюю часть при необходимости уточняй.', 'cam-politeness cam-discourse')

lesson('path-politeness-power','path-modal-remoteness path-register-b2',
 'Одна и та же просьба звучит по-разному другу, коллеге и незнакомому человеку. Важны отношения, нагрузка просьбы и право её предъявить.',
 [('Небольшая просьба и большая услуга','Could you send the link? просит небольшое действие. Could you work all weekend? накладывает большую нагрузку, даже с could. Одного вежливого слова мало: нужны причина, выбор и честный срок.'),
  ('Прямота иногда заботливее','Please leave the building now — уместная ясная инструкция при опасности. Could you perhaps consider leaving… может скрыть срочность. Вежливость не равна максимальной длине и косвенности.'),
  ('Дай реальную возможность ответить','If that is not possible, let me know работает, если отказ действительно допустим. Не маскируй обязательный приказ под свободный выбор. В международной команде полезно явно согласовать ожидания.')],
 [('Could you send the link when you have a moment?','Не мог бы ты прислать ссылку, когда будет минутка?','Небольшая просьба без срочного срока.'),('Please stop the machine now.','Пожалуйста, остановите машину сейчас.','Прямая инструкция уместна, когда важна безопасность.')],
 [('Переведи просьбу коллеге: «Не мог бы ты проверить это до пятницы? Если не получится, скажи».','Could you check this by Friday? If that is not possible, let me know.','Срок и возможность отказа названы прямо.','Вежливость сочетается с понятным действием.'),('Сделай срочную инструкцию ясной: Could you perhaps think about leaving the room now?','Please leave the room now.','Ситуация учебная: нужно немедленно выйти.','Не прячем срочность за длинным смягчением.')],
 'Перед ответом назови отношения, нагрузку и срочность. Меняй форму под эти условия, сохраняя честное содержание просьбы.', 'cam-politeness')

lesson('path-diplomatic-disagreement','path-discussion-b2 path-hedging',
 'Можно не соглашаться ясно и спокойно: признать то, что верно, показать точное расхождение и предложить способ его проверить.',
 [('Признай конкретную сильную сторону','I agree that the plan is faster — реальное согласие с преимуществом. Затем However, speed is not our only criterion. Не хвали весь план, если дальше отвергаешь его целиком: это запутает.'),
  ('Спорь с выводом, не с человеком','The data does not establish the cause обсуждает доказательство. You clearly do not understand the data оценивает человека. Первый вариант оставляет предмет для проверки.'),
  ('Предложи следующий шаг','Could we compare costs before deciding? переводит разногласие в действие. При этом твоя позиция должна оставаться видимой: I cannot support a full launch yet — понятнее туманного I have some thoughts.')],
 [('I agree about the benefit, but not about the timing.','Я согласен насчёт пользы, но не насчёт сроков.','Чётко названа граница согласия.'),('The figures show a change, but they do not establish its cause.','Числа показывают изменение, но не устанавливают его причину.','Возражение относится к выводу, а не к личности.')],
 [('Переведи: «Я согласен с целью, но не с методом».','I agree with the goal, but not with the method.','Назови конкретный предмет разногласия.','Согласие с целью не превращается в согласие со всем планом.'),('Предложи проверку: «Можем ли мы сравнить расходы, прежде чем решить?»','Could we compare costs before deciding?','Before + deciding.','Следующий шаг помогает разрешить содержательный спор.')],
 'В длинном ответе проверь три вещи: что признаёшь, чего не принимаешь и какое новое основание могло бы изменить твою позицию.', 'cam-politeness gmu-hedges')

lesson('path-source-mediation','path-synthesis path-information-density',
 'Другой человек может не знать терминов или не иметь времени читать источники. Нужно передать полезный ему смысл, сохранив границы исходных сведений.',
 [('Начни с задачи адресата','Жителю нужен ответ «что это значит для меня?», руководителю — «что нужно решить?». Можно менять порядок и пояснять термины, но нельзя превращать предварительные данные в гарантию.'),
  ('Сохрани ядро','Кто сообщает, о какой группе, за какой период, с каким ограничением? Эти части нельзя терять при сокращении. Если исключение меняет решение, оно важнее второстепенной красивой детали.'),
  ('Отдели своё предложение','The report finds… передаёт источник. I recommend… вводит твой шаг. Не прячь собственное решение в пересказе так, будто его предписал автор.')],
 [('The report covers one neighborhood, not the whole city.','Отчёт охватывает один район, а не весь город.','При упрощении сохранён масштаб.'),('Based on these findings, I recommend a small trial.','На основе этих результатов я рекомендую небольшую пробу.','Собственная рекомендация явно отделена от результатов.')],
 [('Переведи для неспециалиста: «Данные относятся только к этой группе». Apply only to this group.','The data applies only to this group.','Data apply также допустимо по стилю.','Only удерживает границу применимости.'),('Напиши две короткие фразы: отчёт обнаружил задержки; ты предлагаешь проверить расписание. Found delays; review the schedule.','The report found delays. I recommend reviewing the schedule.','Первая фраза — источник; вторая — твоя рекомендация.','Не приписываем автору отчёта своё решение.')],
 'Составь короткую версию для одной аудитории, затем проверь по исходнику каждое число, условие и авторство мысли.', 'purdue-synthesis purdue-concision')

lesson('path-cross-register','path-register-b2 path-source-mediation',
 'Для друга, команды и публичного объявления нужны разные формы одного сообщения. Смена тона не должна менять обещание или факт.',
 [('Сначала неизменяемый смысл','Запуск разрешён, но только после проверки. В любой версии остаются разрешение и условие. We are definitely opening tomorrow уже подменяет содержание, если проверка ещё не пройдена.'),
  ('Меняй упаковку под читателя','Другу: We can start once the checks are done. Руководству: The launch is authorized subject to completion of the checks. Вторая фраза официальнее, но не должна звучать сильнее по сути.'),
  ('Сокращение не должно выкинуть условие','В заголовке мало места, однако pending approval или after checks могут быть самыми важными словами. Если короткая версия вводит в заблуждение, лучше добавить строку.')],
 [('We can start once the checks are done.','Можно начинать, когда проверки завершатся.','Разговорная версия с сохранённым условием.'),('The launch is authorized subject to completion of the checks.','Запуск разрешён при условии завершения проверок.','Официальная форма того же условия.')],
 [('Сделай проще, сохранив условие: Access is permitted subject to prior registration.','You can enter if you register first.','Prior registration — предварительная регистрация.','Тон проще, право доступа не стало безусловным.'),('Переведи для коллеги: «План одобрен, но дата ещё не подтверждена». Approved; confirmed.','The plan is approved, but the date is not confirmed yet.','Одобрение плана и подтверждение даты — разные факты.','Ни одна аудитория не должна получить выдуманную дату.')],
 'Перед тремя версиями выпиши общий смысл в двух строках. После смены тона сверь каждую версию с этими строками.', 'purdue-concision cam-politeness')

lesson('path-rhetorical-analysis','path-longform-reading path-emphasis-restraint',
 'Риторический разбор объясняет, как текст пытается повлиять на конкретного читателя. Просто назвать метафору недостаточно — нужно показать её работу.',
 [('Кому и чего хочет автор','Реклама, письмо жителю и научная заметка убеждают по-разному. Сначала назови аудиторию и желаемую реакцию: купить, довериться, пересмотреть решение, поддержать пробу.'),
  ('Наблюдение → эффект → опора','Автор повторяет слово local. Возможно, это создаёт чувство принадлежности. Подтверди эффект окружающими фразами, а не только названием приёма. Твой разбор должен быть проверяем по тексту.'),
  ('Убедительность и истинность различаются','Личная история может сильно воздействовать, но не доказывает частоту явления. Хорошо устроенный аргумент может опираться на слабые данные. Оцени обе стороны отдельно.')],
 [('The repeated word our presents the project as a shared responsibility.','Повтор our представляет проект как общую ответственность.','Названы языковая деталь и возможная работа этой детали.'),('The story makes the risk vivid, but does not show how common it is.','История делает риск наглядным, но не показывает его частоту.','Воздействие не перепутано с доказательством.')],
 [('Дано: Our street. Our choice. Our future. Объясни одним английским предложением, что делает повтор our.','Repeating our presents the decision as a shared responsibility.','Shared responsibility — общая ответственность.','Разбор привязан к видимой языковой детали.'),('Переведи: «Пример убедительный, но он не устанавливает частоту проблемы». Persuasive; establish how common the problem is.','The example is persuasive, but it does not establish how common the problem is.','Не приравнивай впечатление к измерению.','Сохранены эффект примера и предел вывода.')],
 'В каждом абзаце разбора держи цепочку: конкретная цитируемая деталь, её возможный эффект, связь с аудиторией и ограничение интерпретации.', 'uvu-rhetoric')

lesson('path-literary-reading','path-reading-inference path-rhetorical-analysis',
 'Рассказчик может замечать не всё, оправдывать себя или понимать события иначе, чем читатель. Учимся видеть это по деталям текста.',
 [('Рассказчик не равен автору','I was always fair — заявление персонажа, а не справка об истине. Посмотри, совпадает ли оно с его поступками и чужими репликами. Не надо сразу объявлять каждую неточность ложью.'),
  ('Две опоры сильнее впечатления','Если герой говорит, что дал свободу, но прячет ключ, между словами и действием возникает напряжение. Это конкретное основание для чтения, а не просто «мне кажется, он плохой».'),
  ('Неоднозначность можно сохранить','The detail suggests… осторожнее, чем The author proves…. Предложи альтернативное чтение и проверь, какие детали оно объясняет хуже. Художественный текст не всегда даёт единственный окончательный диагноз.')],
 [('He claims to trust her, yet he hides the key.','Он говорит, что доверяет ей, но прячет ключ.','Слова сопоставлены с видимым действием.'),('This may suggest fear rather than deliberate cruelty.','Это может указывать на страх, а не на намеренную жестокость.','Интерпретация обозначена как возможная.')],
 [('Прочитай: “I gave her complete freedom,” he said, locking the door. Укажи противоречие одним английским предложением.','His claim of freedom conflicts with his act of locking the door.','Conflicts with — противоречит; act — действие.','Вывод опирается на две детали сцены.'),('Переведи осторожно: «Эта деталь может говорить о ревности». This detail; jealousy.','This detail may suggest jealousy.','Не заменяй may suggest на proves.','Мотив остаётся интерпретацией, если текст не устанавливает его прямо.')],
 'Сначала собери наблюдаемые детали, затем объясни свою версию и одну правдоподобную альтернативу. Не приписывай автору слова рассказчика.', 'uvu-rhetoric purdue-synthesis')

lesson('path-debate-synthesis','path-diplomatic-disagreement path-source-mediation',
 'После обсуждения нужен итог, который сохраняет реальные различия и показывает, что решено, а что осталось открытым.',
 [('Раздели позиции и основания','Один участник ценит доступ, другой опасается расходов. Это могут быть совместимые цели, пока не выбран способ. Перескажи каждую позицию так, чтобы её автор узнал себя.'),
  ('Условное согласие не равно одобрению','I support it if costs stay under the limit нельзя сократить до I support it. В итогах условие должно стоять рядом с согласием, а не исчезать в приложении.'),
  ('Назови открытый вопрос и хозяина шага','We agree to compare two estimates — решение о проверке, а не о полном запуске. Укажи, кто и когда принесёт данные. Если владельца ещё не назначили, так и напиши.')],
 [('Both sides support better access but disagree about the budget.','Обе стороны поддерживают лучший доступ, но расходятся по бюджету.','Общее намерение и разница названы отдельно.'),('The trial is supported only if the cost limit is met.','Пробу поддерживают только при соблюдении лимита расходов.','Условие остаётся частью согласия.')],
 [('Дано: Maya agrees if it starts after three; Leo has not answered. Напиши статус встречи одним предложением.','Maya agrees only if it starts after three, and Leo has not confirmed.','Нельзя писать Everyone agreed.','Сохранены условность одного ответа и отсутствие другого.'),('Переведи: «Мы договорились сравнить варианты, но ещё не выбрали один». Compare the options; choose one.','We agreed to compare the options, but we have not chosen one yet.','Различай решение о процессе и решение о результате.','Итог не ускоряет события.')],
 'В итоговом синтезе используй четыре строки: общее, расхождение, условие, следующий шаг. Затем проверь каждую по репликам.', 'purdue-synthesis cam-discourse')

lesson('path-editing','path-scope-ambiguity path-information-density',
 'Редактура начинается не с красивых слов. Сначала исправляют смысл и логику, затем порядок, затем отдельные формулировки.',
 [('Сначала правда сообщения','Проверь числа, участников, причинные связи и условия. Без этого гладкая фраза может уверенно передавать ошибку. Не добавляй удобную причину, если её нет в источнике.'),
  ('Потом маршрут читателя','Главный ответ должен находиться легко. Перенеси нужное ограничение ближе к выводу. Раздели абзац, если в нём одновременно решение, история и совсем другая просьба.'),
  ('В конце сокращай строку','Убери повторения и пустые обороты. Сохрани полезный термин, если он точен, и поясни его, если читатель новичок. Редактор улучшает чужую мысль, а не незаметно подменяет её своей.')],
 [('Forty people registered; twenty-eight completed the course.','Сорок человек зарегистрировались; двадцать восемь завершили курс.','Два показателя не смешаны.'),('The cause is unknown, so the notice should not name one.','Причина неизвестна, поэтому объявление не должно её называть.','Неизвестное не заполнено правдоподобной выдумкой.')],
 [('Дано: 40 registered, 28 completed. Исправь Forty people completed the course.','Twenty-eight people completed the course.','Сверь именно показатель completed.','Редактура исправляет факт, а не только стиль.'),('Сократи We are in a position to make a decision now до ясной фразы.','We can decide now.','Can decide выражает тот же смысл.','Убраны слова, которые не меняют содержание.')],
 'Редактируй в три прохода: содержание, структура, строка. После последнего прохода вновь проверь ограничения, которые легко потерять при сокращении.', 'purdue-concision purdue-cohesion')

lesson('path-c2-capstone','path-debate-synthesis path-editing path-cross-register',
 'Итоговая работа соединяет навыки: разобраться в вопросе, сопоставить источники, написать для адресата, объяснить устно и пересмотреть позицию после возражения.',
 [('Сузь вопрос до решаемого','«Улучшить образование» слишком широко. «Стоит ли продлевать эту пробу при таком бюджете?» даёт предмет, критерий и ограничение. Сначала сформулируй вопрос, затем собирай материал под него.'),
  ('Разделяй четыре слоя','Факт источника, чужая оценка, твой вывод и твоя рекомендация — разные вещи. Помечай их в заметках. Если данных нет, запиши пробел и какой проверкой его можно закрыть.'),
  ('Защита не равна упрямству','Хороший ответ на возражение может уточнить условие или изменить рекомендацию. После обсуждения назови, что осталось прежним и что ты пересмотрел. Один проект не удостоверяет уровень C2: нужны устойчивые навыки в разных задачах.')],
 [('The evidence supports a trial, not an immediate full launch.','Данные поддерживают пробу, а не немедленный полный запуск.','Масштаб решения соразмерен основаниям.'),('I would change my recommendation if the cost estimate increased.','Я бы изменил рекомендацию, если бы оценка затрат выросла.','Названо условие пересмотра позиции.')],
 [('Сформулируй вопрос проекта по-английски: «Стоит ли продлить пробу ещё на месяц?» Extend the trial; another month.','Should we extend the trial for another month?','Один вопрос, один конкретный выбор.','Такой вопрос позволяет подобрать относящиеся к нему данные.'),('Переведи: «Пока я рекомендую пробу, но сначала нам нужна оценка расходов». For now; a cost estimate.','For now, I recommend a trial, but we need a cost estimate first.','Сохрани временность рекомендации и недостающее основание.','Фраза соединяет позицию с честной границей готовности.')],
 'Здесь можно работать несколькими сессиями: вопрос и источники → черновик → возражение → новая версия → устное объяснение. Сохрани версии для сравнения своего прогресса.', 'purdue-synthesis purdue-concision gmu-hedges')

lesson('extended-c1-lecture','path-lecture-listening path-proposal',
 'В уроке о библиотеке нужно услышать не только идею нового сервиса, но и то, при каких условиях автор готов его поддержать.',
 [('Записывай связи, а не россыпь слов','В конспекте оставляй короткие пары: proposal → reason; benefit → limit. По-русски это «предложение → почему» и «польза → ограничение». Затем из них легче собрать ясное сообщение команде.'),
  ('Условие держи рядом с планом','Only if — «только если», необходимое условие. Not at the expense of — «не за счёт». Если новый сервис разрешён только без ущерба основному, нельзя пересказать его как безусловное расширение.'),
  ('Новые вопросы могут изменить рекомендацию','Сначала работай с m1 и m2. Продолжение m3 открывай на указанном в заданиях этапе. После него сравни версии: что ограничили, что отозвали и что осталось прежним. Это репетиция реакции на новую информацию.')],
 [('The speaker supports a trial only if core services are protected.','Выступающий поддерживает пробу только при сохранении основных услуг.','Условие входит в смысл поддержки; пример отдельный от фактов m1.'),('The answer narrows the proposal rather than withdrawing it.','Ответ сужает предложение, а не отменяет его.','Уточнение и полный отказ различаются.')],
 [('Мини-ситуация: New classes are welcome, but not at the expense of quiet study. Передай условие одним предложением.','New classes are welcome only if quiet study is protected.','Quiet study — спокойная самостоятельная работа.','Сохранено то, что нельзя ухудшить.'),('Переведи: «Выступающий уточнил предложение, но не отказался от него». Clarified; withdraw.','The speaker clarified the proposal but did not withdraw it.','Withdraw — отозвать; clarify — уточнить.','Два разных изменения позиции не смешаны.')],
 'Теперь прослушай m1 без текста и составь короткую карту. Эти мини-примеры не являются фактами о библиотеке: точные сведения бери только из материалов урока.', 'cam-discourse gmu-hedges')

lesson('extended-c1-cross-text','path-synthesis path-hedging path-proposal',
 'Три текста о гибридных занятиях отвечают на разные вопросы: что наблюдали, что пережил участник и что организатор способен обеспечить.',
 [('Подпиши вопрос каждого источника','Исследовательская заметка может измерять посещаемость. Личная колонка показывает, почему человеку помог доступ. Записка организатора объясняет расходы и выполнимость. Не требуй от одного текста ответа на чужой вопрос.'),
  ('Разные данные полезны по-разному','Один личный случай помогает увидеть препятствие, но не показывает долю всех людей с таким препятствием. Посещаемость показывает присутствие, но не автоматически освоение материала. Назови показатель точно.'),
  ('Решение связывай с критериями','Комитету нужен выбор по его запросу m4. Построй ответ вокруг доступности и надёжности работы, а не трёх независимых пересказов. Собственную рекомендацию подпиши как рекомендацию, а не найденный факт.')],
 [('Attendance increased, but learning outcomes were not measured.','Посещаемость выросла, но учебные результаты не измеряли.','Один показатель не подменён другим.'),('The account explains one barrier; it does not show how common that barrier is.','Рассказ объясняет одно препятствие, но не его распространённость.','Личный опыт полезен без превращения в статистику.')],
 [('Переведи: «Заметка измеряет посещаемость, а не знания». The note; measures attendance; knowledge.','The note measures attendance, not knowledge.','Сначала назови именно измеренный показатель.','Не добавляем вывод об усвоении материала.'),('Соедини: A describes access. B explains delivery costs. Одним предложением без выдуманного противоречия.','A describes access, while B explains delivery costs.','While сопоставляет разные стороны.','Различие тем ещё не доказывает спор авторов.')],
 'Прочитай m1–m4 и заполни по строке «вопрос — данные — ограничение». Только после этого пиши рекомендацию комитету.', 'purdue-synthesis gmu-hedges')

lesson('extended-c1-public-explanation','path-synthesis path-hedging',
 'Объяснить показание датчика — значит помочь жителю понять число, не превращая его в обещание безопасности, которого исходник не даёт.',
 [('Что число действительно описывает','Разделяй сигнал, оценку прибором и вывод человека. Measures — измеряет; estimates — оценивает приблизительно; indicates — указывает. Эти глаголы не всегда заменяют друг друга.'),
  ('Место и время — часть числа','One reading at one location относится к одному показанию в одной точке. Не расширяй его на весь район или весь день без оснований. Оговорку ставь рядом с числом, чтобы её не потеряли при пересказе.'),
  ('Для разных читателей — разный вход','Жителю сначала объясни, что он видит. Техническому сотруднику — что нужно проверить. m3 добавляет сцену недопонимания позже; не открывай её до первых заданий. Учебные сведения здесь вымышлены, а не рекомендация по здоровью.')],
 [('The display shows an estimate for this location.','Экран показывает оценку для этой точки.','Сохранены приблизительность и место.'),('This reading alone does not establish conditions across the neighborhood.','Одно это показание не устанавливает условия во всём районе.','Указано конкретное ограничение вывода.')],
 [('Переведи: «Это оценка, а не точное значение». An estimate; an exact value.','This is an estimate, not an exact value.','Оценка не обязательно бесполезна, но её статус важен.','Сохраняем точность описания прибора.'),('Сузь This reading describes the whole city до предоставленной границы: только это место.','This reading describes only this location.','Only this location — только эта точка.','Не расширяем измерение на неизвестную область.')],
 'В основных заданиях сначала выпиши, что измерено, где, когда и чего число не доказывает. Затем объясняй это языком выбранного адресата.', 'purdue-concision gmu-hedges')

lesson('extended-c1-facilitation','path-discussion-b2 path-reporting-verbs',
 'Ведущий встречи помогает группе не потерять разные цели и условия. Молчание участника нельзя автоматически записывать как согласие.',
 [('Дай место ещё не прозвучавшей позиции','We have heard about cost; could we hear about access? возвращает пропущенный критерий. Вызвать человека в разговор можно без давления: Is there anything you would like to add?'),
  ('Перескажи проверяемо','So your concern is the timing, not the goal — полезная проверка понимания. Добавь Have I understood that correctly? Не превращай свою интерпретацию в окончательное мнение собеседника.'),
  ('Фиксируй статус, не желаемый итог','Предложено, поддержано при условии и окончательно согласовано — разные состояния. Материалы m3 и m4 вводят новые сведения поэтапно. Сохраняй старый итог, затем явно обновляй его после новой реплики.')],
 [('We have agreement on the goal, but not yet on the budget.','Мы согласовали цель, но ещё не бюджет.','Итог отмечает и совпадение, и открытый вопрос.'),('Oleg has not commented yet, so we should ask for his view.','Олег ещё не высказался, поэтому нужно спросить его мнение.','Молчание не объявлено согласием.')],
 [('Переведи приглашение тихому участнику: «Хочешь что-нибудь добавить?»','Is there anything you would like to add?','Приглашай, не приписывай заранее позицию.','Фраза открывает человеку возможность высказаться.'),('Дано: все поддержали цель, бюджет не обсуждали. Напиши итог одним английским предложением.','Everyone supports the goal, but the budget has not been discussed.','Has not been discussed — не обсуждался.','Не превращаем отсутствие обсуждения в одобрение.')],
 'Читай этапы в указанном порядке. После каждого обновляй четыре строки: цель, ограничения, согласие, открытый вопрос.', 'cam-politeness cam-discourse')

lesson('extended-c1-review-article','path-longform-reading path-critical-reading',
 'Рецензия объясняет оценку произведения через конкретные сцены. Проблемная статья использует произведение как вход к более широкому вопросу.',
 [('Сцена → приём → впечатление','Назови, что показано или слышно, затем как это сделано и что даёт зрителю. «Фильм трогательный» — итог без основания. «Долгая пауза оставляет нас рядом с ожиданием героя» уже объясняет впечатление.'),
  ('Разные жанры задают разные вопросы','Рецензия помогает понять, как работает фильм. Статья может обсуждать труд, память или доступ к культуре. Смена жанра требует нового центра текста, а не только более официальных слов.'),
  ('Не выдумывай сцены ради сильной мысли','Материалы содержат вымышленные фильмы и сведения о них. Оценивай только предоставленные детали; собственную интерпретацию обозначай. Поздний запрос редактора открывай на этапе задания — он меняет задачу текста.')],
 [('The long silence makes the viewer notice the character’s hesitation.','Долгая тишина заставляет зрителя заметить колебание персонажа.','Оценка связана с конкретным приёмом.'),('The review evaluates the film; the article explores the issue it raises.','Рецензия оценивает фильм; статья разбирает поднятую им проблему.','Жанры различаются целью, а не длиной слов.')],
 [('Переведи: «Сцена показывает ожидание, а не объясняет его словами». The scene; shows waiting; explains it in words.','The scene shows waiting rather than explaining it in words.','Rather than + -ing после shows waiting.','Назван конкретный способ рассказа.'),('Разверни The film is moving в одну обоснованную фразу. Мини-факт: долгие паузы показывают одиночество. Long pauses; loneliness.','The film is moving because its long pauses convey loneliness.','Convey — передавать ощущение.','Добавлена опора для оценки, а не ещё один усилитель.')],
 'Сначала привяжи каждую оценку к сцене из материалов. Когда изменится редакционный запрос, перестрой главный вопрос, сохранив проверяемые детали.', 'uvu-rhetoric purdue-concision')

lesson('extended-c1-lexical-lab','path-lexical-precision path-preposition-patterns',
 'Знакомое слово может ошибочно попасть в знакомую конструкцию. В этой мастерской проверяем значение, форму и соседние слова вместе.',
 [('Сначала значение в ситуации','Issue может быть вопросом/проблемой или номером журнала. После выбора значения понятнее артикль и сочетание: an issue to resolve либо the latest issue. Перевод «вопрос» не подходит к любому issue.'),
  ('Потом рамка','Address an issue — заняться проблемой; relevant to — относящийся к; comply with — соблюдать. Проверка одного окончания не исправит неверный предлог или глагол рядом.'),
  ('Правка должна сохранить сообщение','В m1 есть намеренные ошибки, а m2 даёт справку. Меняй только то, что мешает нужному смыслу. В m3 знакомые слова попадают в другую тему — сначала заново установи значение.')],
 [('We need to address this issue before Friday.','Нам нужно заняться этой проблемой до пятницы.','Address здесь не про почтовый адрес.'),('The latest issue contains an interview.','Последний номер содержит интервью.','Issue здесь — выпуск журнала.')],
 [('Переведи: «Нужно решить эту проблему». We need to; address this issue.','We need to address this issue.','Address может употребляться как глагол «заняться вопросом».','Правильная пара слов передаёт рабочее действие.'),('Переведи: «Я прочитал последний номер журнала». The latest issue of the magazine.','I read the latest issue of the magazine.','Здесь issue — не проблема.','Контекст определяет нужное значение знакомого слова.')],
 'Для каждой правки запиши короткую причину: значение, исчисляемость, предлог или сочетаемость. Не заменяй все знакомые слова редкими синонимами.', 'purdue-concision cam-substitution')

lesson('extended-c2-literary','path-literary-reading path-scope-ambiguity',
 'В «Последнем ключе» нужно держать рядом слова рассказчика, его действия и возможные другие чтения сцены.',
 [('Отдели наблюдаемое от мотива','Герой взял ключ — деталь сцены. Он хочет сохранить власть — объяснение мотива. Второе может быть сильным чтением, но требует нескольких опор и не должно маскироваться под прямую цитату.'),
  ('Смена формы меняет доступ к мысли','Проза может давать внутренний голос; пьеса — реплики, паузы и действия на сцене. Сравни не только одинаковые события, но и то, что зритель теперь должен выводить без рассказчика.'),
  ('Спор читателей проверяй по тексту','В m3 есть разные оценки. Не выбирай по уверенности тона. Найди для каждой поддерживающую и осложняющую деталь. Итог может сохранить напряжение между заботой и контролем.')],
 [('His action supports this reading, but does not prove his motive.','Его действие поддерживает это чтение, но не доказывает мотив.','Различаются видимое действие и внутреннее объяснение.'),('The stage version makes the hesitation visible rather than narrating it.','Сценическая версия показывает колебание, а не рассказывает о нём.','Сравнивается способ передачи, а не только сюжет.')],
 [('Мини-сцена: герой говорит You are free to leave, но кладёт ключ в карман. Напиши одно противоречие.','His words suggest freedom, but putting the key in his pocket suggests control.','Suggests — указывает, а не proves.','Две опоры позволяют обсудить неоднозначность.'),('Переведи: «Это правдоподобное чтение, но другая деталь его осложняет». A plausible reading; another detail complicates it.','This is a plausible reading, but another detail complicates it.','Не обязательно полностью отвергать интерпретацию.','Сильный анализ допускает мешающие детали.')],
 'В основных заданиях используй точные детали «Последнего ключа», а не учебную мини-сцену выше. Для каждой трактовки сохрани хотя бы одно реальное осложнение.', 'uvu-rhetoric purdue-synthesis')

lesson('extended-c2-synthesis','path-source-mediation path-proposal',
 'При культурном финансировании массовый охват и культурная ценность могут быть разными критериями. Нужно сопоставить позиции без подмены одного другим.',
 [('Уточни меру успеха','Attendance — посещаемость; reach — охват; value — ценность. Большое число посетителей отвечает не на все вопросы о пользе проекта. Маленькая аудитория тоже сама по себе не доказывает высокую ценность.'),
  ('Восстанови сильную версию обеих сторон','Автор о доступе может заботиться о реальном участии, а не просто о красивом числе. Автор о сохранении культуры может защищать редкий опыт, а не любые расходы. Не упрощай позицию до удобной мишени.'),
  ('Рекомендация должна выдержать ограничения','Используй досье m3 для выполнимости решения. Не добавляй статистику или согласие авторов, которого нет. Объясни, какой критерий выбран и какой компромисс остаётся.')],
 [('A larger audience does not automatically mean greater cultural value.','Большая аудитория не означает автоматически большую культурную ценность.','Показатель охвата не объявлен единственной мерой.'),('The sources disagree about priorities, not necessarily about the facts.','Источники расходятся в приоритетах, но не обязательно в фактах.','Разные оценки отделены от фактического противоречия.')],
 [('Переведи: «Охват вырос, но качество участия не измеряли». Reach; quality of participation.','Reach increased, but the quality of participation was not measured.','Два разных показателя.','Сохраняем полезный факт и границу вывода.'),('Переведи: «Оба автора ценят доступ, но по-разному расставляют приоритеты». Value access; set different priorities.','Both authors value access, but they set different priorities.','Не называй частичное расхождение полным отрицанием.','Позиции представлены без искусственного полярного спора.')],
 'Прочитай критерии и бюджет из досье, затем строй рекомендацию. Каждый новый вывод помечай как свой и показывай, на какие сведения он опирается.', 'purdue-synthesis gmu-hedges')

lesson('extended-c2-interview','path-implicature path-reporting-verbs',
 'В интервью о городской памяти позиция может уточняться через осторожный ответ, поправку вопроса или отказ принять его предпосылку.',
 [('Слушай, на что ответили','Интервьюер спрашивает о поддержке проекта, а собеседник говорит о важности памяти. Это может быть обход прямого ответа. Не записывай поддержку проекта, если подтвердили только общую ценность.'),
  ('Замечай слова, уменьшающие масштаб','Some, so far, in this case, not necessarily сужают утверждение. Если убрать их из пересказа, осторожная позиция превратится в универсальную. Сохраняй такую границу рядом с главным тезисом.'),
  ('Подтекст проверяй альтернативой','Сдержанный тон может означать сомнение, осторожность или просто манеру речи. В ответе отдели явную реплику от твоего чтения и укажи, что подтвердило бы его. Сценарная репетиция не равна спонтанному интервью.')],
 [('She values the archive but has not endorsed the plan.','Она ценит архив, но ещё не поддержала план.','Одобрение общей ценности не подменяет согласие с решением.'),('Her answer may signal a reservation, although she does not reject the idea.','Её ответ может выражать оговорку, хотя идею она не отвергает.','Осторожная интерпретация не становится прямым отказом.')],
 [('Дано: “History matters, but I have not seen the final plan.” Напиши, чего говорящий пока не подтвердил.','The speaker has not endorsed the final plan.','Endorse — явно поддержать.','Слова о значимости истории не доказывают одобрение проекта.'),('Переведи: «Это моя интерпретация, а не её прямое утверждение». My interpretation; her explicit statement.','This is my interpretation, not her explicit statement.','Explicit — прямо выраженный.','В пересказе сохранено авторство вывода.')],
 'Сначала собери таблицу явных ответов. Подтекст добавляй отдельным слоем с опорой на конкретные реплики и возможной альтернативой.', 'cam-discourse cam-politeness')

lesson('extended-c2-consensus','path-debate-synthesis path-diplomatic-disagreement',
 'При обсуждении доступа в мастерскую важно не просто добиться слова yes, а установить, какие условия каждая сторона действительно принимает.',
 [('Выдели интерес за вариантом','«Открывать позже» — вариант; «не потерять доступ после работы» — интерес. Разные варианты могут решать один интерес. Перескажи интерес, прежде чем предлагать компромисс.'),
  ('Согласие бывает ограниченным','I can support that if… — поддержка только при условии. В протоколе нельзя отрезать if-часть. Также не считай отсутствие возражения окончательной поддержкой без проверки.'),
  ('Новая информация меняет доступные решения','Материалы идут этапами. После нового ограничения сначала проверь, какой прежний вариант стал невыполним, и только затем переформулируй предложение. Не делай вид, что ограничение было известно изначально.')],
 [('We agree on the aim, but access arrangements remain unresolved.','Мы согласны с целью, но порядок доступа пока не решён.','Общая цель не выдана за готовый договор.'),('That option is no longer workable under the new restriction.','Этот вариант больше не выполним при новом ограничении.','Решение пересматривается из-за новых данных.')],
 [('Переведи: «Я поддержу это, только если доступ останется бесплатным». Access remains free.','I will support this only if access remains free.','Only if — обязательное условие поддержки.','При сокращении условие нельзя потерять.'),('Напиши статус: цель согласована, часы работы ещё нет. Opening hours.','The goal is agreed, but the opening hours are not settled yet.','Settled — согласованы окончательно.','Не создаём ложного ощущения завершённой договорённости.')],
 'После каждого этапа перепиши статус решения. В итог включи условия каждой стороны, нерешённый пункт и конкретную следующую проверку.', 'cam-politeness purdue-synthesis')

lesson('extended-c2-editor','path-editing path-advanced-negation',
 'Редактор публичной аналитики отвечает за то, чтобы читатель не принял красивые формулировки за более сильные данные, чем есть на самом деле.',
 [('Сверяй название показателя','Registered, eligible, applied, completed называют разные группы. Число верное, но подпись неверная — уже фактическая ошибка. При каждой цифре найди в справке, кого именно считали.'),
  ('Проверяй переход от числа к причине','После запуска число заявок выросло — последовательность. Запуск вызвал рост — причинный вывод. Если дизайн наблюдения этого не устанавливает, исправь глагол, а не только добавь perhaps в конце.'),
  ('Поправка должна находиться легко','В поздней сцене редакторского обмена важен уже опубликованный текст. Чётко назови, что было неверно и что подтверждено. Причину ошибки указывай только если она установлена; не придумывай технический сбой.')],
 [('The figure refers to applications, not completed projects.','Число относится к заявкам, а не к завершённым проектам.','Сохранён правильный показатель.'),('The increase followed the pilot, but the cause has not been established.','Рост последовал за пробным проектом, но причина не установлена.','Хронология не выдана за причинность.')],
 [('Мини-данные: 30 applications, 18 approvals. Исправь Thirty applications were approved.','Eighteen applications were approved.','Approved — одобрены; не путай с submitted.','Правим смысл числа, а не стилистический оттенок.'),('Переведи: «Мы исправили число; причина ошибки пока неизвестна». Corrected the figure; unknown.','We corrected the figure; the cause of the error is still unknown.','Не заполняй unknown удобной догадкой.','Поправка сообщает проверенное и сохраняет границу знания.')],
 'Работай сначала со справкой, затем со структурой публикации. Для каждой правки оставь объяснение, какая ошибочная картина возникала бы у читателя.', 'purdue-concision gmu-hedges')

lesson('extended-c2-register-performance','path-cross-register path-politeness-power',
 'В этом сценарии одно условное решение нужно передать разным людям и затем исправить возникшее недопонимание, не меняя факты.',
 [('Что уже разрешено','Authorized — разрешено. Proposed — предложено. Pending approval — ожидает одобрения. Сначала прочитай статус в m2: эти слова не взаимозаменяемы, даже если звучат официально.'),
  ('Условие идёт вместе с обещанием','Можно сократить объяснение для друга, но нельзя убрать ограничение по доступу, сроку или расходам, если оно влияет на решение. Публичная версия особенно уязвима к цитированию одной строки.'),
  ('Ремонт смысла после реакции','В m3 и m4 собеседники добавят новые реакции и сведения. Сначала назови, что было понято неверно, затем повтори действительное решение обычными словами. Не обвиняй слушателя вместо прояснения своей фразы.')],
 [('The pilot is authorized, but it has not started yet.','Пробный проект разрешён, но ещё не начался.','Разрешение не подменено свершившимся действием.'),('Let me clarify: approval does not remove the stated conditions.','Уточню: одобрение не отменяет указанные условия.','Поправка делает границу решения явной.')],
 [('Переведи другу: «Нам разрешили пробу, но сначала надо закончить проверки». Finish the checks first.','We have permission for a trial, but we need to finish the checks first.','Простой тон не должен стирать порядок действий.','Разрешение и условие сохранены.'),('Исправь недопонимание “So it has already started?”: одобрено, но не началось.','It has been approved, but it has not started yet.','Approved и started — разные статусы.','Поправка отвечает именно на неверный вывод слушателя.')],
 'Сначала подготовь краткое смысловое ядро из m1–m2. Сохрани его при смене адресата, затем обновляй только на основании новых этапов.', 'cam-politeness purdue-concision')

lesson('extended-c1-conversion','path-word-formation path-lexical-precision',
 'В английском существительное иногда становится глаголом без новой части слова: an email → email me. Но новое действие должно быть понятно в ситуации.',
 [('Форма та же, работа другая','A text — сообщение; text me — напиши мне. Место в предложении показывает роль. Глагол получает обычные окончания: texted, texting. Это не отдельное волшебное правило без грамматики.'),
  ('Не каждое превращение удачно','Привычное email the team сразу понятно. Самодельный глагол может заставить международную команду гадать. Если у слова несколько значений, добавь ясное дополнение или используй обычный глагол.'),
  ('Проверь различия вариантов','Table a proposal может пониматься по-разному в американском и британском контексте. Для международной команды postpone discussion или put it on the agenda яснее — выбери именно нужное действие.')],
 [('Please email the team.','Пожалуйста, напиши команде по электронной почте.','Email работает как глагол с ясным получателем.'),('Let us postpone discussion of the proposal.','Давайте отложим обсуждение предложения.','Прямой глагол убирает возможную путаницу с table.')],
 [('Переведи: «Напиши мне, когда приедешь». Text me; when you arrive.','Text me when you arrive.','Text — здесь глагол, не предмет.','В when-части для будущего используем настоящее arrive.'),('Международная команда должна отложить обсуждение. Замени We will table it на однозначную фразу.','We will postpone discussion of it.','Postpone — отложить; без двусмысленного table.','Ясность действия важнее демонстрации краткого идиоматичного глагола.')],
 'Разбирая историю и продолжение, проверяй у каждого нового глагола действие и адресата. При межвариантной неоднозначности формулируй прямо.', 'cam-conversion')

lesson('extended-c2-shakespeare-idioms','path-idioms-context path-irony',
 'Литературное выражение может жить в обычной речи, но нынешнее значение, ирония и историческое происхождение — три отдельных вопроса.',
 [('Сначала пойми сегодняшнюю ситуацию','В современном тексте идиома может не требовать знания пьесы. Объясни её обычными словами и проверь, подходит ли она к сцене. Узнавание красивой цитаты не заменяет понимания сообщения.'),
  ('Встречается у автора — не значит изобретено им','Attested in означает, что выражение засвидетельствовано в тексте. Invented by утверждает авторство изобретения и требует другого доказательства. Не расширяй литературную ссылку до исторической гарантии.'),
  ('Публичный текст требует проверки тона','Ироническая идиома может звучать как насмешка над людьми, хотя автор хотел пошутить о ситуации. Назови вероятное чтение и предложи прямую версию. Новые реакции редактора вводятся позднее по сценарию.')],
 [('The phrase appears in the play; that does not prove that the playwright invented it.','Фраза встречается в пьесе; это не доказывает, что драматург её изобрёл.','Свидетельство употребления отделено от происхождения.'),('A neutral paraphrase makes the criticism clearer.','Нейтральный пересказ делает критику яснее.','Убираем двусмысленный образ, сохраняя мысль.')],
 [('Переведи осторожную историческую формулировку: «Выражение встречается в этой пьесе». The expression; appears.','The expression appears in this play.','Не добавляй invented без основания.','Утверждается только проверяемое присутствие в тексте.'),('Исправь This proves that Shakespeare invented the phrase, если известно лишь, что фраза встречается в пьесе.','This shows that the phrase appears in Shakespeare’s play, not that he invented it.','Shows occurrence — показывает употребление.','Правка уменьшает вывод до силы основания.')],
 'В материалах m2 проверяй нынешнее значение отдельно от литературной ссылки. В журнальной версии объясни образ так, чтобы читателю не требовалось заранее знать пьесу.', 'cam-last-straw uvu-rhetoric')

lesson('extended-c1-sea-coast','path-lexical-precision path-hedging',
 'В тексте о меняющемся береге слова должны помочь представить место и не спутать обычные природные процессы с оценкой будущего риска.',
 [('Построй карту в словах','Coast — прибрежная зона; shore — край воды; estuary — устье, где река выходит к морю и взаимодействует с приливом. Along, inland, upstream задают направление. Сначала расположи объекты, затем обсуждай решение.'),
  ('Не смешивай похожие процессы','Tide — приливно-отливное движение уровня; current — течение; storm surge — штормовой нагон. Если заменить одно другим, поменяется описываемый процесс, а не только стиль.'),
  ('Наблюдение не равно гарантии','An estimate — оценка; a projection — расчёт будущего при допущениях; a guarantee — обещание исхода. В споре жителей передавай каждое с правильной силой. m3 слушай на указанном этапе; это синтетический учебный сценарий.')],
 [('The path runs along the shore before turning inland.','Дорожка идёт вдоль берега, затем поворачивает вглубь суши.','Читатель может восстановить направление.'),('The projection describes a possible future under stated assumptions.','Прогноз описывает возможное будущее при указанных допущениях.','Расчёт не выдан за неизбежный исход.')],
 [('Переведи: «Дорожка поворачивает вглубь суши». The path; turns inland.','The path turns inland.','Inland — от берега в сторону суши.','Одно точное направление помогает построить карту.'),('Переведи: «Это оценка риска, а не гарантия». A risk estimate; a guarantee.','This is a risk estimate, not a guarantee.','Сохрани статус числа или прогноза.','Ни обещание безопасности, ни обещание ущерба не добавлено.')],
 'В основных заданиях сначала нарисуй мысленную карту Greyhaven по m1. Все местные числа и выводы бери из сценария, не из этих отдельных мини-примеров.', 'gmu-hedges purdue-concision')

lesson('extended-c2-built-environment','path-source-mediation path-rhetorical-analysis',
 'Архитектурный текст должен помочь увидеть здание, понять, как им пользуются, и оценить предложение без путаницы между внешним видом и функцией.',
 [('Опиши маршрут наблюдателя','Сначала назови сторону здания, вход и связь помещений. Facade — внешняя сторона, особенно главный фасад; layout — расположение частей; circulation — движение людей внутри. Термин нужен только там, где различие помогает понять место.'),
  ('Сохранять вид и сохранять использование — разное','Можно оставить фасад и сильно изменить внутреннюю планировку. Preserve, restore, adapt обозначают разные действия. В рекомендации уточни, что именно сохраняется и что изменяется.'),
  ('Оценка требует причины','A welcoming space — оценка. Объясни, какая деталь её поддерживает: понятный вход, обзор, место для ожидания. Не выдавай предположение об удобстве за установленное техническое соответствие. Новые требования m3 появляются позже.')],
 [('The entrance faces the square, while the courtyard lies behind the building.','Вход обращён к площади, а двор расположен позади здания.','Даны отношения, по которым можно представить место.'),('The proposal preserves the facade but changes the internal layout.','Предложение сохраняет фасад, но меняет внутреннюю планировку.','Разделено, что остаётся и что меняется.')],
 [('Переведи: «Двор находится за зданием». The courtyard; behind the building.','The courtyard is behind the building.','Сначала точное расположение, потом оценка.','Простой пространственный факт не требует сложной терминологии.'),('Переведи: «План сохраняет фасад, но меняет использование здания». Preserves the facade; changes how the building is used.','The plan preserves the facade but changes how the building is used.','Внешний вид и функция — отдельные стороны решения.','Не утверждаем, что сохранено всё здание без изменений.')],
 'Теперь опиши Alder House по материалам, а затем сопоставь критерии авторов. В колонке каждая оценка должна опираться на видимую деталь или прямо названное требование.', 'purdue-concision uvu-rhetoric')

lesson('extended-c1-adjective-scope','path-advanced-negation path-articles-advanced',
 'Два прилагательных могут отдельно описывать предмет или одно может уточнять уже готовый тип предмета. От этого зависят смысл и иногда запятая.',
 [('Два отдельных качества','A plain, sturdy bench — скамья простая и прочная. Качества можно представить отдельно и соединить and. Запятая отражает такую независимость, а не просто количество прилагательных.'),
  ('Качество плюс тип','A compact medical cabinet — компактный медицинский шкаф. Medical cabinet называет тип, а compact описывает его размер. Вставить and между compact и medical без изменения смысла труднее.'),
  ('Тесты помогают, но смысл главнее','Замена порядка или вставка and — подсказки, а не безошибочная машина. Our old friend может означать давнего друга, не старого по возрасту. Если подпись допускает нежелательное чтение, распиши смысл словами.')],
 [('They bought a plain, sturdy bench.','Они купили простую прочную скамью.','Два независимых качества одного предмета.'),('They bought a compact medical cabinet.','Они купили компактный медицинский шкаф.','Размер относится к предмету определённого типа.')],
 [('Передай два независимых качества: «Стул удобный и практичный». The chair; comfortable; practical.','The chair is comfortable and practical.','Здесь and показывает независимость качеств.','Сначала смысл, потом решаем форму перед существительным.'),('Убери возрастную неоднозначность: Daniel is an old friend. Нужно «мы дружим много лет».','Daniel has been my friend for many years.','Не называй возраст Дэниела.','Полная фраза уточняет, к чему относилось old.')],
 'Разбирая подписи выставки, сначала запиши нужный смысл обычным предложением. Затем выбирай порядок, запятую или явное пояснение.', 'cam-adjectives cam-focus')

lesson('extended-c1-visual-data','path-comparatives path-hedging path-synthesis',
 'График требует назвать, кого считали и от какого общего числа брали долю. Иначе верные числа легко превращаются в неверную историю.',
 [('Количество и доля отвечают на разные вопросы','Count — сколько людей. Share — какая часть всех ответивших. Если людей стало больше, количество категории может вырасти даже при снижении её доли. Поэтому сначала прочитай заголовок, оси и общее число.'),
  ('Проценты и процентные пункты','С 20% до 30% — рост на 10 процентных пунктов. Относительно прежних 20% это рост на 50%. Не называй первое изменение просто «на 10%», если имеешь в виду разность долей.'),
  ('Две группы не обязательно те же люди','Опрос января и опрос июня могут включать разных участников. Тогда нельзя заявить, сколько конкретных людей пересели на велосипед. Рост после кампании также сам по себе не доказывает её причинный эффект.')],
 [('The share rose from 20% to 30%, an increase of 10 percentage points.','Доля выросла с 20% до 30%, то есть на 10 процентных пунктов.','Разность долей названа в нужных единицах.'),('The count increased, although the share fell.','Количество выросло, хотя доля снизилась.','Это возможно при увеличении общего числа участников.')],
 [('Переведи мини-данные: «Доля снизилась с 40% до 30%, на 10 процентных пунктов». The share; fell.','The share fell from 40% to 30%, a decrease of 10 percentage points.','Это пример для тренировки, не цифры основного графика.','Процентные пункты — вычитание двух долей.'),('Дано: отдельные добровольные опросы в январе и июне. Исправь We tracked the same people.','We compared separate samples; we did not track the same people.','Separate samples — отдельные выборки.','Если связь участников не установлена, нельзя заявлять индивидуальные переходы.')],
 'В m1–m2 сначала прочитай шкалы, легенду и состав опроса. Считай по реальным учебным данным этих графиков; цифры подготовительного примера к ним не относятся.', 'gmu-hedges purdue-synthesis')

lesson('research-spoken-grammar','path-repair-conversation path-ellipsis',
 'В живой речи человек строит мысль на ходу: сначала называет тему, потом дополняет, уточняет или исправляет её. Это не всегда ошибка.',
 [('Тема появляется раньше полной фразы','That cafe, is it open? Сначала называем предмет разговора, затем задаём вопрос. Такой начальный «ярлык темы» называют head. В обычном письме часто проще Is that cafe open?'),
  ('Уточнение можно добавить в конце','It is useful, that app — название добавлено после основной мысли; это tail. Так говорящий напоминает, о чём речь. I mean вводит поправку: three tickets — I mean, four.'),
  ('Живую речь и письмо оценивай по задаче','Повтор местоимения может помогать слушателю, но перегружать отчёт. Переписывая устный рассказ, сохраняй смысл и убирай только ненужные следы поиска слов. Не объявляй всякое несовпадение с книжным предложением неграмотностью.')],
 [('That new app, have you tried it?','Это новое приложение — ты его пробовал?','Сначала обозначена тема, затем вопрос.'),('We need three tickets — I mean, four.','Нам нужны три билета — то есть четыре.','Говорящий явно исправляет количество.')],
 [('Сделай нейтральный письменный вопрос: That new cafe, is it open?','Is that new cafe open?','Вопрос уже содержит весь предмет.','Убираем устную отдельную тему, не меняя содержания.'),('Переведи самопоправление: «Нам нужны две копии — нет, три». Copies; I mean.','We need two copies — I mean, three.','Поправка должна быть слышна явно.','Слушатель понимает, что итоговое число — три.')],
 'В разговорных заданиях разрешай себе уточнять и достраивать мысль. Затем сравни устную запись с более компактной письменной версией.', 'cam-spoken cam-discourse')

lesson('research-accent-adaptation','path-sound-basics path-connected-speech path-prosody',
 'Непривычный акцент может скрывать знакомое слово. Учимся сопоставлять разные звуковые версии, сохраняя собственную понятную американскую модель.',
 [('Слово известно, звук непривычен','В разных вариантах английского /r/ после гласного слышно не всегда; американские water и better часто содержат короткий удар языка, похожий на быстрый d. Это закономерные варианты, а не небрежность каждого отдельного человека.'),
  ('Сравни одну фразу, а не весь акцент','Возьми короткое слово у двух реальных говорящих. Сначала догадайся на слух, затем посмотри текст. Запиши одно различие: гласный, /r/, ударение или связка. Не нужно сразу копировать всё произношение.'),
  ('Цель — понимать и быть понятным','Сохраняй последовательную модель произношения для своей речи. При незнакомом звучании уточняй слово, не оценивай акцент. Синтетические голоса не заменяют всё разнообразие реальных голосов.')],
 [('I know the word, but I am used to a different pronunciation.','Я знаю слово, но привык к другому произношению.','Трудность слуха отделена от незнания значения.'),('Could you repeat that last word?','Не могли бы вы повторить последнее слово?','Уточнение относится к конкретному месту, а не качеству акцента.')],
 [('Переведи: «Мне знакомо это слово, но не такое произношение». Familiar with; pronunciation.','I am familiar with the word, but not with that pronunciation.','Familiar with — знаком с.','Различаем знание слова и привычную звуковую форму.'),('Исправь грубое уточнение Your accent is wrong в просьбу повторить последнее слово.','Could you repeat the last word, please?','Проси нужное действие без оценки человека.','Понимание улучшается конкретным уточнением.')],
 'В заданиях с двумя голосами используй законно доступные человеческие записи и сохрани ссылки. Здесь нет встроенной пары записей, подтверждающей сравнение акцентов.', 'rachel-stress cam-spoken')

lesson('research-question-response','path-questions-basic path-ellipsis path-prosody',
 'Короткий вопрос в ответ может показывать интерес, удивление или проверять деталь. Его форму выбирают по исходной реплике, а намерение — по контексту.',
 [('Подхвати помощника из реплики','She has changed her plans. — Has she? Помощник has подхватывает present perfect. She called. — Did she? Для обычного прошедшего нужен did. В разговоре есть варианты реакций, но сейчас тренируем именно согласованную рамку.'),
  ('Выдели удивившую деталь','You invited how many people? повторяет сообщение, оставляя вопрос на неожиданном числе. Это не обычный нейтральный порядок вопроса, а эхо-уточнение. Для первого запроса проще How many people did you invite?'),
  ('Реакция ещё не согласие','I see может означать «понимаю, что ты говоришь», без поддержки предложения. Интонация помогает, но не гарантирует смысл. Если решение важно, спроси Are you agreeing to the plan?')],
 [('She has changed her plans. — Has she?','Она изменила планы. — Правда?','Повторён has из исходной формы.'),('You invited how many people?','Ты пригласил сколько человек?','Вопрос выделяет неожиданное количество.')],
 [('Ответь коротким вопросом интереса на He has finished, сохранив помощник.','Has he?','Has уже есть в исходной реплике.','Не меняем эту учебную рамку на past simple.'),('Переведи нейтральную проверку: «Это означает, что ты согласен с планом?»','Does that mean you agree with the plan?','Реакция I see сама по себе не доказала согласие.','Уточнение делает нужный статус явным.')],
 'После тренировки формы произнеси реакции с ясным продолжением. Не полагайся только на тон, когда важно понять согласие или обязательство.', 'cam-discourse bc-ellipsis')

lesson('research-discourse-listening','path-debate-synthesis research-question-response',
 'В разговоре нескольких людей итог меняется: один предложил дату, другой назвал препятствие, третий согласился только после определённого времени.',
 [('У каждой идеи есть владелец и статус','Для конспекта нужны не только слова Monday и three. Запиши: кто предложил, кто поддержал, при каком условии. Might work — возможный вариант, не бронирование.'),
  ('Поправка заменяет старую версию','In that case, Monday? может сменить предложение о пятнице. Но новый вопрос не означает подтверждение всеми. Ищи явное согласие и проверь, совпали ли дата и время.'),
  ('Текстовая репетиция готовит к слуху','Сначала разбери написанный диалог. Затем послушай или озвучь роли без чтения и восстанови карту. Собственное чтение ролей — репетиция, а не доказательство понимания настоящего многоголосного разговора.')],
 [('Monday is proposed, but the time is not confirmed.','Понедельник предложен, но время не подтверждено.','Предложение отделено от договорённости.'),('Nina can attend only if the meeting starts after three.','Нина может прийти только если встреча начнётся после трёх.','Условие сохранено рядом с участником.')],
 [('Мини-диалог: “Tuesday might work.” — “I need to check.” Напиши статус одним предложением.','Tuesday has been suggested, but it has not been confirmed.','Suggested — предложен; confirmed — подтверждён.','Отсутствие отказа не означает согласие.'),('Переведи: «Пятницу исключили, а понедельник пока не подтвердили». Ruled out; confirmed.','Friday was ruled out, and Monday has not been confirmed yet.','Две даты имеют разные статусы.','Не превращаем оставшийся вариант в принятое решение.')],
 'В исходном диалоге отмечай каждую смену статуса. Для внешней записи в последнем задании нужен доступный тебе аудиофрагмент: урок не содержит его автоматически.', 'cam-discourse purdue-synthesis')

lesson('research-public-correction','path-editing path-source-mediation',
 'Публичная поправка должна быстро вернуть читателю правильный факт и показать, что именно в прежнем сообщении было перепутано.',
 [('Два показателя — два названия','Registered — зарегистрировались; completed — завершили. В мини-кейсе урока число 80 относится к регистрации, 56 — к завершению. Нельзя исправить одно, случайно изменив другое.'),
  ('Скажи старую ошибку и новый факт','Our earlier notice incorrectly stated… задаёт ошибочную формулировку. The correct figure is… даёт исправление. Не прячь поправку в длинной истории о том, как старалась команда.'),
  ('Причину не выдумываем','Если источник ошибки не установлен, скажи The cause is being checked или The cause is unknown — по фактам. Ни обвинение программы, ни оценка качества курса не следуют автоматически из этой путаницы.')],
 [('Eighty people registered; fifty-six completed the course.','Восемьдесят человек зарегистрировались; пятьдесят шесть завершили курс.','Каждое число связано с правильным показателем.'),('The earlier notice confused registrations with completions.','Прежнее объявление перепутало регистрации и завершения.','Ошибка названа прямо и конкретно.')],
 [('Переведи: «Ранее мы неверно указали число завершивших курс». Earlier; incorrectly stated; the number of people who completed the course.','Earlier, we incorrectly stated the number of people who completed the course.','Назови исправляемый показатель полностью.','Не размываем поправку до vague some confusion.'),('Напиши верный короткий факт по кейсу: 80 registered, 56 completed.','Eighty people registered, and fifty-six completed the course.','Оба числа нужны со своими глаголами.','Поправка не превращает 56 в число зарегистрированных.')],
 'Теперь составь публичную версию: что перепутали, какие числа верны, что о причине известно. Проверки для команды вынеси отдельно от сообщения читателю.', 'purdue-concision gmu-hedges')

lesson('sustained-clock-history','path-longform-reading path-literary-reading path-source-mediation',
 'Длинная статья о городских часах учит удерживать связь между началом, поздними свидетельствами и пересмотром главного вопроса.',
 [('Первый проход — без охоты за каждой деталью','Прочитай m1 целиком и коротко назови, как меняется вопрос текста. Сначала речь может идти о ремонте, затем о памяти и праве представлять прошлое. Не открывай поздние материалы, чтобы увидеть, как текст сам меняет твоё понимание.'),
  ('Возвращайся по конкретной связи','Во втором проходе сопоставляй указанные абзацы: что было сказано раньше и чем поздняя деталь это ограничила? Дата, воспоминание и число наклеек — разные типы свидетельств; одно не заменяет другое.'),
  ('Отложенный перенос — новый случай','m3 меняет часть сведений позднее; сохрани предыдущую версию ответа и объясни изменение. m4 оставь на 24–48 часов: задача проверяет перенос способа рассуждения, а не память о фразах про часы.')],
 [('The later paragraph changes how we read the opening detail.','Поздний абзац меняет то, как мы понимаем начальную деталь.','Смысл строится между удалёнными частями текста.'),('The new evidence narrows the claim but does not overturn it completely.','Новое свидетельство сужает утверждение, но не опровергает его полностью.','Изменение вывода описано точно по масштабу.')],
 [('Переведи: «В начале вопрос кажется техническим, но позже становится вопросом памяти». Technical; a question of memory.','At first, the question seems technical, but later it becomes a question of memory.','Назови поворот главного вопроса, а не весь сюжет.','Это форма заметки о структуре длинного текста.'),('Переведи: «Новое свидетельство уточняет вывод, но не доказывает противоположное». The new evidence; qualifies the conclusion; proves the opposite.','The new evidence qualifies the conclusion but does not prove the opposite.','Qualifies — уточняет или ограничивает здесь.','Не превращаем частичную поправку в полный разворот.')],
 'Теперь переходи к статье и соблюдай порядок m1 → m2 → m3 → отложенный m4. Подготовительные фразы не заменяют чтение целого текста.', 'purdue-synthesis uvu-rhetoric')

lesson('natural-c1-teams','path-lecture-listening research-question-response path-hedging',
 'В настоящем разговоре NASA нужно различить два голоса и понять, как каждый уточняет популярное представление о работе команды.',
 [('Одна запись, два вопроса','Перед первым прослушиванием держи два ярлыка: счастье и продуктивность; виды конфликта. Сначала свяжи вопрос с говорящим. Не пытайся одновременно записать все слова и сделать большой вывод.'),
  ('Уточнение — отдельная позиция','Говорящий может не отвергать связь полностью, а менять её направление или условия. Лови but, not necessarily и противопоставления. «Конфликт бывает полезен» не разрешает личные выпады: нужен точный вид разногласия.'),
  ('Проверь слух по транскрипту после ответа','Запись в m1 — человеческая; m2 — официальный текст, который может сглаживать особенности звучания. После своей попытки найди место расхождения, снова послушай его и исправь именно эту мысль. В m3 дан новый вымышленный случай для переноса.')],
 [('The speaker is qualifying the claim, not rejecting every part of it.','Выступающий уточняет утверждение, а не отвергает всё целиком.','Полезная рамка для описания частичного согласия.'),('A disagreement about the task is different from a personal attack.','Спор о задаче отличается от личного выпада.','Различие типов конфликта важно для практического вывода.')],
 [('Переведи: «Она уточняет связь, а не полностью отрицает её». Qualifies the relationship; rejects it completely.','She qualifies the relationship rather than rejecting it completely.','Это подготовительная языковая рамка; точный ответ бери из аудио.','Сохраняется промежуточная позиция между да и нет.'),('Переведи: «Мы можем оспорить расчёт, не нападая на человека». Question the calculation; attack the person.','We can question the calculation without attacking the person.','Without + -ing.','Несогласие относится к проверяемой работе, а не личности.')],
 'Включи m1 без m2. Сначала раздели голоса и предметы разговора, затем уточни аргументы. Учебные рамки выше не являются цитатами NASA.', 'nasa-teams rachel-stress')

