def build():
    from editorial_guard import require_historical_restore
    require_historical_restore()
    assigned = []
    for p in [ROOT/'content/curriculum.json', *sorted((ROOT/'content/courses').glob('*.json'))]:
        if 'cinema' in p.name:
            continue
        data = json.loads(p.read_text(encoding='utf-8'))
        for item in data.get('lessons',[]) if isinstance(data,dict) else data:
            if item.get('level','').startswith(('C1','C2')):
                assigned.append(item['id'])
    ids = [x['lessonId'] for x in LESSONS]
    assert len(ids) == len(set(ids))
    assert set(ids) == set(assigned), (set(assigned)-set(ids),set(ids)-set(assigned))
    sources = [dict(id=id,title=title,url=url,kind=kind,notes=notes) for id,title,url,kind,notes in SOURCES]
    source_ids = {x['id'] for x in sources}
    for item in LESSONS:
        assert len(item['explanation'])==3 and len(item['examples'])==2 and len(item['practice'])==2
        assert set(item['sourceIds']) <= source_ids
        assert item['lessonId'] not in item['prerequisites']
    target=ROOT/'content/course-guides-c1-c2.json'
    target.write_text(json.dumps(dict(version=1,sources=sources,lessons=LESSONS),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Wrote {len(LESSONS)} guides, {sum(len(x["practice"]) for x in LESSONS)} preparatory exercises to {target.name}')

if __name__ == '__main__':
    build()
